NAME = 'NorSMB: Studentmållagsbibelen frå 1921'
BOOK = 'I Samuel'

CHAPTERS = {
    1: {
        1: 'Elkana heitte ein mann, ein sufit som budde i Rama, på Efraimsheidi. Han var son åt Jeroham, son åt Elihu, son åt Tohu, son åt Suf, ein efraimit.',
        2: 'Han hadde tvo konor; Hanna heitte den eine, Peninna heitte hi. Peninna hadde born, men Hanna var barnlaus.',
        3: 'År etter år drog denne mannen upp frå byen sin, og tilbad og ofra i Silo til Herren, allhers drott. Der var dei tvo Eli-sønerne Hofni og Pinehas prestar for Herren.',
        4: 'Alltid når Elkana ofra, gav han Peninna, kona si, og alle sønerne og døtterne hennar kvar sin lut.',
        5: 'Men Hanna gav han ein lut for tvo; for han elska Hanna, endå Herren hadde stengt morslivet hennar.',
        6: 'Og medtevlaren hennar erga og terga henne, og vilde øsa henne upp i egse, for di Herren hadde stengt morslivet hennar.',
        7: 'Soleis gjorde han år etter år, kvar gong ho kom upp til Herrens hus; ho terga henne sameleis. Og då gret ho og vilde ikkje eta.',
        8: 'Elkana, mannen hennar, sagde til henne: «Hanna, kvifor græt du? og kvifor et du ikkje? Og kvifor er du so hugsjuk? Er ikkje eg meir for deg enn ti søner?»',
        9: 'Ein gong dei hadde ete og drukke i Silo, reis Hanna upp - presten Eli sat på ein stol attmed den eine dørstolpen til Herrens heilagdom -',
        10: 'Og i hjartans sut bad ho til Herren og gret sårt.',
        11: 'Og ho gjorde ein lovnad og sagde: «Herre, du allhers drott! vil du venda augo til vesaldomen åt trælkvinna di og tenkja på meg, og ikkje gløyma trælkvinna di, men gjeva trælkvinna di eit gutebarn, so vil eg vigja honom til Herren for alle hans livedagar, og aldri skal det koma saks på hovudet hans.»',
        12: 'Ho heldt lenge på og bad framfor Herren. Og Eli fylgde munnen hennar med augo;',
        13: 'for Hanna bad ikkje høgt; ho leda berre lipporne, men mælet høyrdest ikkje. So trudde Eli ho var drukki.',
        14: 'Difor sagde til henne: «Kor lenge vil du syna deg drukki? Sjå til å få ruset til å siga av deg!»',
        15: 'Men Hanna svara: «Nei, herre! eg er ei sorgtyngd kona. Vin og rusdrykk hev eg ikkje drukke; men eg hev rent ut hjarta mitt for Herren.',
        16: 'Haldt ikkje trælkvinna di for ei uvyrda! for det er utav stor sorg og trege eg hev tala heile tida.»',
        17: 'Eli svara og sagde: «Far i fred! Israels Gud skal gjeva deg det du hev bede honom um!»',
        18: 'Då sagde ho: «Å gjev trælkvinna di må finna godvilje hjå deg!» So gjekk ho sin veg, og fekk seg mat, og ho synte ikkje suti si meir.',
        19: 'Morgonen etter reis dei upp tidleg og heldt bøn framfor Herren. So for dei attende og kom til Rama. Elkana budde saman med Hanna, kona si, og Herren kom henne i hug.',
        20: 'Då det hadde lide ei tid, vart Hanna med barn, og åtte ein son, som ho kalla Samuel; «for», sagde ho, «eg hev bede Herren um honom.»',
        21: 'Elkana drog upp med heile huslyden sin og ofra til Herren det årlege slagtofferet sitt, og offer han hadde lova.',
        22: 'Men Hanna drog ikkje med. Ho sagde til mannen sin: «Eg vil bia til dess vesleguten er avvand. Då vil eg føra honom med meg og syna honom fram for Herren, so han sidan kann halda til der alle dagar.»',
        23: 'Elkana, mannen hennar, sagde med henne: «Gjer som du tykkjer best. Bia til dess du hev vant honom av. Berre Herren må gjera etter sitt ord!» So var kona att heime og hadde son sin til brjostet, til dess ho vande honom av.',
        24: 'Men då han var avvand, tok ho honom med dit upp, og hadde med seg tri uksar, ei skjeppa mjøl og ei vinhit, og ho førde honom inn i Herrens hus i Silo. Men han var berre ein liten gut.',
        25: 'Dei slagta uksen, og førde so vesleguten til Eli.',
        26: 'Ho sagde: «Høyr, herre! so sant du liver, herre, so er eg den kona som stod her attmed deg og bad til Herren.',
        27: 'Um denne guten bad eg, og Herren høyrde bøni mi og gav meg det eg bad um.',
        28: 'Difor gjev eg honom att til Herren, so han skal vera ei gåva frå Herren alle sine livedager.» Og dei bad til Herren der.',
    },
    2: {
        1: 'Då bad Hanna og sagde: «Hjarta mitt frygdar seg i Herren, høgreist er hornet mitt i Herren. Med vidopen munn ropar eg mot fiendarne mine, for di eg fegnast for frelsa di.',
        2: 'Ingen er heilag som Herren, ingen er til utan du. Det bid inkje berg som vår Gud.',
        3: 'Slutta med kyt og kaute ord! Slepp ikkje agelause ord or munnen! For Herren er Gud som allting veit, og verki deim veg han vel.',
        4: 'Brosten vert bogen åt kjemporne, men dei ustøde fær styrkebelte på.',
        5: 'Dei som fyrr fekk sin mette, lyt leiga seg burt for mat, men dei som svalt, svelt ikkje meir. Barnlaus kona fær borni sju, barnerik mor folnar og fåst.',
        6: 'Herren er den som tek liv og gjev liv, han fører ned til Helheim og upp derifrå.',
        7: 'Herren er den som gjer arm og gjer rik. Han dreg ned, men lyfter ogso upp.',
        8: 'Han reiser den ringe or moldi, og lyfter den låge or søyla, og leider han til sætes millom hovdingar og gjev han eit æresæte. Grunnstolparne åt jordi høyrer Herren til, på deim han bygde manneheimen.',
        9: 'Han held vakt og hegnar vegen åt dei gudlege, men gudlaust folk forferst i myrkret; for aldri mannen vinn med eigi magt.',
        10: 'Deim som strider imot Herren, skræmer han, i himmelen yver deim dundrar han. Herren dømer jordi frå ende til annan, han aukar krafti hjå kongen sin. Han hevjar hornet høgt åt den han salvar.»',
        11: 'Elkana for heim att til Rama. Men guten gjorde tenesta for Herren hjå presten Eli.',
        12: 'Men sønerne åt Eli var uvyrdor; dei ansa ikkje Herren,',
        13: 'og ikkje heller kva prestarne med rette kunde krevja av folket. Kvar gong ein mann ofra slagtoffer, kom drengen åt presten medan kjøtet koka, og hadde ein tritinda gaffel i handi,',
        14: 'og stakk honom ned i gryta eller kjeraldet eller kjelen eller krukka; og alt som hekk fast på gaffelen, tok presten. Soleis for dei med alle israelitar som kom dit til Silo.',
        15: 'Ja endå fyrr enn feittet var brent, kom prestedrengen og sagde til mannen som ofra: «Hit med steikjekjøt til presten! han vil ikkje hava kokt kjøt hjå deg, berre rått.»',
        16: 'Um då mannen sagde: «Fyrst må eg brenna feittet; sidan kann du taka alt det du lyster!» svara han: «Nei, kom straks med det! Elles tek eg det med magt.»',
        17: 'Den ovstore syndi dei unge prestarne gjorde beint i augo på Herren; vart so mykje større av di dei lærde folket svivyrda offeret til Herren.',
        18: 'Samuel gjorde tenesta for Herrens åsyn. Alt medan han var smågut, var han klædd i ein messehakel av lin.',
        19: 'Dessutan laga mor hans ein liten kjole kvart år honom og hadde med seg, når ho kom med mannen sin og ofra det årvisse slagtofferet.',
        20: 'Då velsigna Eli Elkana og kona hans og sagde: «Herren gjeve deg fleire born med denne kona, i staden for honom som ho hev bede um i bøn til Herren!» So for dei heim att.',
        21: 'Og Herren kom i hug Hanna, og ho vart med barn og åtte tri søner og tvo døtter. Men guten Samuel voks upp hjå Herren.',
        22: 'Eli var svært gamall. Han høyrde gjete alt det sønerne hans gjorde mot heile Israel, og at dei låg med dei kvinnorne som gjorde tenesta ved inngangen til møtetjeldet.',
        23: 'Og han sagde då: «Kvifor fer de soleis åt? Eg høyrer heile folket talar um all den vonde framferdi dykkar.',
        24: 'Gjer ikkje so, sønerne mine! det hev ikkje noko godt lov, so som eg høyrer ordet gjeng um dykk frå mann til mann millom Herrens folk.',
        25: 'Når folk syndar mot einannan, so dømer Gud deim imillom. Men når nokon syndar mot Herren, kven skal då ganga imillom?» Men dei lydde ikkje på ordi åt far sin; for Herren hadde etla deim til å døy.',
        26: 'Men guten Samuel voks og mannast, og vann godhug både hjå Gud og menneskje.',
        27: 'Ein gudsmann kom då til Eli og sagde til honom: «So segjer Herren: «For farsætti di openberra eg meg den tid dei var i Egyptarland og træla for Faraos hus.',
        28: 'Eg valde henne millom alle Israels ætter til prestenesta mi, til å ofra på altaret mitt og brenna røykjelse og bera messehakel for mi åsyn. Og eg gav farsætti di offerretterne frå Israels-borni.',
        29: 'Kvifor trakkar de då på slagtofferi og grjonofferi mine som eg skipa til i min bustad? Kor kann du æra sønerne dine meir enn meg, so det godnar dykk med det beste av kvar offergåva som Israel, folket mitt, ber fram?»',
        30: 'Difor lyder ordet frå Herren, Israels Gud: «Vel hev eg sagt: Di ætt og farsætti di skal få gjera tenesta for mi åsyn alltid og æveleg.» Men no lyder Herrens ord: «Aldri i verdi! deim som ærar meg, deim vil eg æra; dei som vanvyrder meg, skal verta til skammar.',
        31: 'Sjå dei dagar kjem då eg høgg av din arm og armen åt farsætti di, so ingen vert gamall i ætti di.',
        32: 'Og du skal sjå Guds bustad i naud, endå so mykje godt Herren gjer mot Israel. Og ingen skal nokon sinne verta gamall i ætti di.',
        33: 'Berre ein einaste av di ætt vil eg ikkje rydja burt frå altaret mitt, so eg sløkkjer ut augo dine, og syg mergen or beini dine; og alle som veks upp i ditt hus, skal døy i dei beste manndomsåri.',
        34: 'Og det skal du hava til merke, det som kjem yver sønerne dine, Hofni og Pinehas: på ein dag skal dei båe døy.',
        35: 'Eg vil reisa meg upp ein pålitande prest som gjer etter min hug og vilje. Åt honom vil eg byggja eit traust hus, so han allstødt skal gjera tenesta framfor den eg salvar.',
        36: 'Då vil det henda at alle som vert att i ætti di, kjem og kastar seg å gruve for honom og tiggar um ein skilling eller ein brødleiv, og segjer: «Kjære væne, set meg til medhjelpar i eit av preste-embætti dine, so eg kann få ein bite mat å eta!»»»',
    },
    3: {
        1: 'Guten Samuel gjorde tenesta for Herren hjå Eli. Herrens ord var dyrt i dei dagarne, og profetsynerne var sjeldfengde.',
        2: 'Då bar det so til med Eli låg i det vanlege kvileromet sitt - han tok til å dimmast på syni, so han ikkje kunde skilja -',
        3: 'og dei endå ikkje hadde sløkt Guds lampa, og Samuel sov i Herrens heilagdom, der Guds kista stod:',
        4: 'då ropa Herren på Samuel, og han svara: «Ja, her er eg.»',
        5: 'Han sprang til Eli og sagde: «Her er eg, du ropa på meg.» Han svara: «Nei, eg ropa ikkje; gakk og legg deg att!» Han gjekk og lagde seg.',
        6: 'Herren ropa ein gong til: «Samuel!» Samuel reis upp og gjekk til Eli og sagde: «Ja, her er eg, du ropa på meg!» Han svara: «Nei, eg ropa ikkje, guten min! gakk og legg deg att!»',
        7: 'Samuel hadde ikkje endå lært å kjenna Herren; Herrens ord hadde ikkje openberra seg for honom endå.',
        8: 'Tridje venda heldt Herren fram og ropa på Samuel. Han reis upp og gjekk til Eli og sagde: «Ja, her er eg, du ropa på meg.» Då skyna Eli det var Herren som ropa på guten.',
        9: 'Og Eli sagde til Samuel: «Gakk du og legg deg! Hender det so at einkvan ropar på deg, skal du svara: «Tala, Herre! tenaren din høyrer!»» Samuel gjekk og lagde seg i romet sitt.',
        10: 'Då so Herren gjekk innåt og ropa som gongerne fyrr: «Samuel, Samuel!» då svara Samuel: «Tala, Herre! tenaren din høyrer.»',
        11: 'Då sagde Herren til Samuel: «Eg kjem til å gjera verk i Israel som kjem til å ringja for båe øyro på deim som høyrer det.',
        12: 'På den dagen skal eg lata koma yver Eli alt det eg hev tala um ætti hans, frå fyrst til sist.',
        13: 'Eg hev kunngjort for honom at eg vil døma ætti hans til æveleg tid, for den misgjerning som han visste um, at sønerne hans drog forbanning yver seg, og likevel aga han deim ikkje.',
        14: 'Difor hev eg svore Eli-ætti: «Aldri i æva skal syndi i Eli-ætti kunna sonast antan med slagtoffer eller noko anna offer.»»',
        15: 'Samuel vart liggjande til morgons, då han skulde opna dørerne til Herrens hus. Samuel torde ikkje fortelja Eli um syni.',
        16: 'Men Eli ropa på Samuel, og sagde: «Samuel, guten min!» Han svara: «Her er eg.»',
        17: 'Han sagde: «Kva var det Gud tala til deg? Kjære, dyl det ikkje for meg! Gud late deg bøta no og sidan, dersom du løynar noko for meg av det han tala til deg!»',
        18: 'So fortalde Samuel alt saman, og løynde ingen ting for honom. Eli svara: Han er Herren. Han gjere som tekkjest honom!',
        19: 'Samuel voks til, og Herren, var med honom, og let ikkje eitt av alle sine ord falla til jordi.',
        20: 'Heile Israel frå Dan til Be’erseba skyna at Samuel var utvald til profet for Herren.',
        21: 'Og Herren heldt fram med å syna seg i Silo. For Herren openberra seg for Samuel i Silo gjenom Herrens ord.',
    },
    4: {
        1: 'Og heile Israel høyrde Samuels ord. Israel drog ut til strid mot filistarane og lægra seg ved Eben-Ezer, medan filistarane lægra seg i Afek.',
        2: 'Filistarane fylkte heren sin mot Israel, og striden vart drjug. Og Israel tapte for filistarane; dei felte umlag fire tusund mann på vigvollen.',
        3: 'Då no folket kom att til lægret, sagde dei øvste i Israel: «Kvifor hev Herren late filistarane slå oss i dag? Lat oss henta Herrens sambandskista frå Silo, so ho kann vera her hjå oss og frelsa oss frå fiendarne våre!»',
        4: 'Folket sende bod til Silo og tok derifrå sambandskista åt Herren, allhers drott, han som tronar yver kerubarne. Og dei tvo Eli-sønerne, Hofni og Pinehas, fylgde med Guds sambandskista.',
        5: 'Då Herrens sambandskista kom til lægret, då losna det so stort eit fagnadrop frå heile Israel, at jordi dunde.',
        6: 'Då filistarane høyrde ljoden av fagnadropet, sagde dei: «Kva tyder dette glymjande fagnadropet i hebræarlægret?» Og då dei vart vise med at Herrens kista var komi til lægret,',
        7: 'vart dei forfærde; for dei tenkte: «Gud er komen til lægret.» Og dei sagde: «Usæle me! sovore hev aldri hendt fyrr!',
        8: 'Usæle me! kven skal frelsa oss frå denne velduge Guden? Det var denne Guden som sende alle ulukkorne yver egyptarane i øydemarki.',
        9: 'Men - manna dykk upp! og far fram på kara vis, filistarar, so ikkje de skal verta trælar for hebræarane, liksom dei hev vore trælar for oss! Ver no karar, og gakk på!»',
        10: 'Filistarane kasta seg inn i striden; Israels-sønerne vart slegne, og lagde på sprang kvar til sitt, og mannefallet vart øgjelegt stort; av Israel fall tretti tusund mann fotfolk.',
        11: 'Og Guds kista fall i fiendehand, og Hofni og Pinehas, båe Eli-sønerne, let livet.',
        12: 'Ein mann av Benjamin sprang frå slagmarki og nådde Silo same dagen, med sundrivne klæde og mold på hovudet.',
        13: 'Då han kom dit, sat Eli på stolen sin attmed byporten og einstirde utetter vegen; for hjarta hans bivra av otte for Guds kista. Då mannen kom inn i byen med denne tidendi, tok heile byen til å jamra og klaga.',
        14: 'Og då Eli høyrde ljoden av klageropet, spurde han: «Kva tyder dette ståket eg høyrer?» Mannen skunda seg burtåt og fortalde det med Eli.',
        15: 'Eli var åtte og nitti år gamall og star-blind, so han inkje kunde sjå.',
        16: 'Mannen sagde til Eli: «Det er eg som kjem frå slagmarki, eg hev rømt frå striden i dag.» Han spurde: «Korleis hev det gjenge då, guten min?»',
        17: 'Bodberaren svara: «Israel rømde for filistarane, det vart stort mannefall på folket, Hofni og Pinehas, sønerne dine, er falne, og Guds kista hev falle i fiendehand.»',
        18: 'Då han nemnde Guds kista, datt Eli attlenges av stolen attmed byporten og braut halsbeinet. Det vart banen hans; for mannen var gamall og før. Han hadde då vore domar i Israel i fyrti år.',
        19: 'Verdotter hans, kona åt Pinehas, var med barn og gjekk på fallande føter. Då ho høyrde gjete at Guds kista var falli i fiendehand, og at verfaren og mannen hennar hadde late livet, so seig ho i kne og fødde; for føderiderne kom yver henne.',
        20: 'Då ho var mest inni dauden, sagde kvendi som stod ikring henne: «Ver hugheil! du hev fenge ein son.» Men ho svara inkje, og agta ikkje på det.',
        21: 'Ho kalla guten I-kabod: «Kvorven er herlegdomen frå Israel,» sagde ho. Ho kom i hug Guds kista som var falli i fiendehand, og so verfaren og mannen.',
        22: '«Kvorven er herlegdomen frå Israel,» sagde ho, «for Guds kista var falli i fiendehand.»',
    },
    5: {
        1: 'Filistarane tok Guds kista og førde henne frå Eben-Ezer til Asdod.',
        2: 'Der tok filistarane Guds sambandskista og bar henne inn i Dagons tempel og sette henne attmed Dagon.',
        3: 'Då Asdod-folki kom dit tidleg morgonen etter, fekk dei sjå Dagon liggja å gruve på golvet framanfor Herrens kista; dei tok då Dagon og sette honom på staden sin att.',
        4: 'Men då dei kom tidleg næste morgon, fann dei Dagon liggjande å gruve framfor Herrens kista, og hovudet og båe henderne hans var avbrotne og låg på dørstokken; berre bulen var att.',
        5: 'Difor er det so i Asdod den dag i dag, at ingen trøder på Dagons dørstokk, korkje nokon av Dagons-prestarne eller nokon annan som gjeng inn i Dagons tempel.',
        6: 'Herrens hand låg tung på Asdod-folki; og han øyde deim og søkte deim med svullsott både i Asdodbyen og i kverven umkring.',
        7: 'Då Asdod-buarne skyna korleis det hekk i hop, sagde dei: «Kista åt Israels Gud må ikkje lenger vera hjå oss; for handi hans ligg tung på oss og på Dagon, guden vår.»',
        8: 'Dei sende då bod og stemnde saman til seg alle filistarfyrstarne, og spurde deim kva dei skulde gjera med kista åt Israels Gud. Dei svara: «Me lyt flytja kista åt Israels Gud til Gat.» Og dei so gjorde.',
        9: 'Men etter dei hadde flutt henne dit, kom Herrens hand yver byen og fjetra deim reint. Og han søkte byfolket med sott, so det braut ut svullar på både små og store.',
        10: 'Dei sende då Guds kista til Ekron. Men då Guds kista kom dit, skreik Ekron-buarne og sagde: «No hev dei flutt kista åt Israels Gud til meg og vil drepa meg og folket mitt!»',
        11: 'Dei sende då bod og stemnde alle filistarfyrstarne saman og sagde: «Send burt kista åt Israels Gud, og lat henne koma heim att til rette staden sin, og ikkje tyna meg og folket mitt!» Ein daudsens angest hadde gripe heile byen; for Guds hand låg ovtung på deim.',
        12: 'Dei folki som ikkje døydde, vart søkte med svullsot. Og klageropet frå byen steig upp til himmelen.',
    },
    6: {
        1: 'Då Herrens kista hadde vore sju månader i Filistarlandet,',
        2: 'kalla filistarane saman prestarne og spåmennerne sine, og spurde: «Kva skal me gjera med Guds kista? Seg oss korleis me skal sende henne heim att!»',
        3: 'Dei svara: «Vil de senda burt kista åt Israels Gud, må de ikkje senda henne gåvelaus; de lyt bera sonoffer åt honom til vederlag; so vert de lækte, og det vil få vita kvifor handi hans ikkje hev vike frå dykk.»',
        4: 'Dei spurde då: «Kva sonoffer skal me gjeva honom?» Dei svara: «Fem svullar av gull og fem myser av gull, like mange som filistarfyrstarne; for de hev alle vore ute for same plåga, fyrstarne dykkar ogso.',
        5: 'De skal laga likner av svullarne dykkar og likner av mysene som legg landet i øyde, og soleis gjeva Israels Gud æra. Kann henda han då tek burt si tunge handi frå dykk, frå guden dykkar og frå landet dykkar.',
        6: 'Kvifor skal de herda dykk til, liksom egyptarane og Farao gjorde? Laut dei ikkje sleppa Israel av stad, etter han hadde fare ille med deim?',
        7: 'Tak no og gjer ei ny vogn, og tak tvo kyr som gjev suga og som aldri hev bore ok! So skal det setja deim for vogni, men taka frå deim kalvarne og lata deim vera heime.',
        8: 'Tak so Herrens kista og set henne på vogni, og legg gulltyet som de gjev honom til sonoffer i ein kistel ved sida av henne, og send henne av garde soleis!',
        9: 'So skal de sjå etter: tek ho vegen heim att til Bet-Semes; so er det han som hev valda oss all denne store ulukka. Men gjer ho ikkje det, veit me det er ikkje hans hand som hev slege oss; men ein vanlagnad som me hev vore ute fyre.»',
        10: 'Folket so gjorde: dei tok tvo kyr som gav suga, og sette deim for vogni, men kalvarne stengde dei inne heime.',
        11: 'Dei sette Herrens kista på vogni, og attmed henne kistelen med myserne av gull og liknerne av svullarne.',
        12: 'Og kyrne for beine vegen fram heilt til Bet-Semes. Dei heldt seg jamt til ålmannvegen, og gjekk i eitt rautande, og bøygde korkje til høgre eller vinstre. Og filistarfyrstarne fylgde etter, alt til landskilet ved Bet-Semes.',
        13: 'Bet-Semes-buarne var ute på kveitehausting i dalen. Då dei såg upp, gådde dei sambandskista; og dei vart fegne då dei såg henne.',
        14: 'Og då vogni kom inn på åkeren til ein Bet-Semes-bonde, Josva, stogga ho der. Der var ein stor stein. Og dei hogg sund treverket på vogni og ofra kyrne til brennoffer for Herren.',
        15: 'Levitarne tok og lyfte ned Herrens kista og kistelen som stod attmed, og som gulltyet var i, og sette deim på den store steinen. Bet-Semes-buarne ofra brennoffer og slagta slagtoffer til Herren den dagen.',
        16: 'Då dei fem filistarfyrstarne hadde skoda på dette, snudde dei heim att til Ekron same dagen.',
        17: 'Dette var dei gullsvullarne som filistarane gav i soningsgåva til Herren: ein for Asdod, ein for Gaza, ein for Askalon, ein for Gat, ein for Ekron.',
        18: 'Og myserne av gull var likso mange som alle filistarbyarne - både festningsbyar og landsbyar - under dei fem fyrstarne. Den store steinen der dei sette Herrens kista, er vitne um dette til no, på åkeren til Bet-Semes-bonden Josva.',
        19: 'Sume av folket i Bet-Semes fekk ogso sott, av di dei hadde skoda på Herrens kista: sytti mann av folket. Folket syrgde, av di Herren hadde gjort so stort mannefall millom folket.',
        20: 'Og Bet-Semes-buarne sagde: «Kven kann standa seg for Herren, den heilage Gud? og kven vil han no heimsøkja når han dreg upp frå oss?»',
        21: 'Dei sende bod til deim som budde i Kirjat-Jearim, og sagde: «Filistarane hev sendt heim att Herrens kista. Kom hit ned og før henne upp til dykk!»',
    },
    7: {
        1: 'So kom då folk frå Kirjat-Jearim og henta Herrens kista dit upp og sette henne inn i Abinadabs hus på haugen. Dei helga Eleazar, son hans, til å vakta Herrens kista.',
        2: 'Frå den dagen då kista kom til Kirjat-Jearim, leid det lang tid: tjuge år. Og heile Israels-ætti sukka etter Herren.',
        3: 'Då tala Samuel til heile Israels-ætti: «Vil de venda um til Herren av heile dykkar hug, so skil dykk med dei framande gudarne og Astarte-bilæti! vend hugen dykkar til Herren, og ten einast honom, so skal han fria dykk frå filistarmagti;»',
        4: 'Då skilde Israels-borni seg bilæti av Ba’al og Astarte og tente einast Herren.',
        5: 'Samuel sagde: «Stemne heile Israel i Mispa, so vil eg beda for dykk til Herren!»',
        6: 'Då samla dei seg saman i Mispa, henta vatn og dei auste ut for Herren, og dei fasta heile den dagen og sagde: «Me hev synda mot Herren.» So heldt Samuel dom i Mispa og skilde trættor millom Israels-borni.',
        7: 'Då filistarane frette at Israels-borni hadde samla seg i Mispa, drog filistarfyrstarne dit upp mot Israel. Då Israel høyrde gjete det, vart dei rædde for filistarane.',
        8: 'Og Israels-borni sagde til Samuel: «Haldt ved i eino og ropa til Herren, vår Gud, at han må frelsa oss ut or filistarmagti!»',
        9: 'Då tok Samuel eit soglamb og ofra det til eit brennoffer, eit heiloffer for Herren. Og Samuel ropa til Herren for Israel. Og Herren høyrde bøni hans.',
        10: 'Medan Samuel ofra brennofferet, drog filistarane fram til strid mot Israel. Men Herren dundra med eit veldugt torever yver filistarane den dagen og fjetra deim, so dei vart slegne av Israel.',
        11: 'Israels mannskap drog ut frå Mispa og forfylgde filistarane og hogg deim ned på flugti, alt til dei kom nedanfor Bet-Kar.',
        12: 'Då tok Samuel ein stein og sette millom Mispa og Sen, og kalla honom Eben-Ezer og sagde: «Til no hev Herren hjelpt oss.»',
        13: 'Soleis laut filistarane bøygja seg, og kom ikkje meir innanfor landskilet åt Israel. Og Herrens hand var mot filistarane so lenge Samuel livde.',
        14: 'Dei byarne som filistarane hadde teke frå Israel, fekk Israel att, frå Ekron til Gat; og kverven derikring tok Israel ogso att frå filistarane. Og millom Israel og amoritarne vart det fred.',
        15: 'Samuel var domar i Israel so lenge han livde.',
        16: 'Kvart år ferdast han rundt til Betel, Gilgal og Mispa; og han skilde trættor i Israel på alle desse staderne.',
        17: 'So for han heim att til Rama; for der åtte han heime, og der skilde han elles trættorne millom israelitarne. Og der bygde han eit altar for Herren.',
    },
    8: {
        1: 'Då Samuel vart gamall, sette han sønerne sine til domarar i Israel.',
        2: 'Fyrstefødde son hans heitte Joel, andre son hans Abia; dei heldt dom i Be’erseba.',
        3: 'Men sønerne fylgde ikkje hans fotefar; dei let seg lokka av låk vinning og tok mutor, og rengde retten.',
        4: 'Alle dei øvste i Israel samla seg då og kom til Samuel i Rama.',
        5: 'Dei sagde til honom: «Sjå, du hev vorte gamall, og sønerne dine fylgjer ikkje dine fotefar. So set no ein konge yver oss til å skifta rett, liksom alle dei hine folki hev!»',
        6: 'Men Samuel mislika dette, at dei sagde: «Gjev oss ein konge til å skilja trættorne våre!» Og Samuel bad til Herren.',
        7: 'Men Herren sagde til Samuel: «Lyd folkekravet! Ikkje deg hev dei vanda; meg hev dei vanda, og vil ikkje hava meg til konge lenger.',
        8: 'Liksom dei hev fare åt alle dagar frå den tid eg førde deim upp frå Egyptarland, då dei snudde ryggen til meg og tente andre gudar; soleis fer dei ogso åt mot deg.',
        9: 'Lyd kravet deira! Men vara deim ålvorleg, og seg kva rett ein konge tek seg når han rikjer yver deim!»',
        10: 'Og Samuel fortalde til folket som kravde ein konge av honom, alt det Herren hadde sagt.',
        11: 'Han sagde: «Dette tek han seg rett til, den kongen som kjem til å rikja yver dykk: Sønerne dykkar vil han taka og bruka framfor vognerne og hestarne sine, so dei lyt springa framfyre vognerne;',
        12: 'sume vil han setja til førarar og underførarar for herflokkerne sine; sume vil han setja til å pløgja åkerjordi si og til å gjera skurdonni og laga krigsvåpni sine og køyregreidorne sine;',
        13: 'og døtterne dykkar vil han taka til å laga kryddesalve og til å koka og baka.',
        14: 'Dei beste åkrarne og vinhagarne og oljeplantingarne dykkar vil han taka og gjeva åt tenarane sine.',
        15: 'Han vil taka tiend av såjordi og vinhagarne dykkar og gjeva henne åt hirdmennerne og tenarane sine.',
        16: 'Dessutan vil han taka tenestdrengjerne og tenestgjentorne dykkar og dei likaste unggutarne dykkar, og asni dykkar vil han taka og bruka i si eigi tenesta.',
        17: 'Av buskapen dykkar vil han taka tiend, og de lyt sjølve vera trælarne hans.',
        18: 'Då vil de ropa til Herren for den kongen skuld som de sjølv hev valt dykk. Men då vil han ikkje svara dykk.»',
        19: 'Men folket vilde ikkje lyda Samuel; «Nei,» sagde dei, «so sanneleg vil me hava ein konge.',
        20: 'Me vil vera jamgode med alle dei hine folki; me vil hava ein konge til domar og til hovding yver heren i krig.»',
        21: 'Då Samuel høyrde alt det folket sagde, bar han det fram for Herren.',
        22: 'Og Herren sagde til Samuel: «Lyd deim og set ein konge yver deim!» Då sagde Samuel til Israels-sønerne: «Far heim kvar til sin by!»',
    },
    9: {
        1: 'Kis heitt ein mann av Benjamin. Han var son åt Abiel, son åt Seror, son åt Bekorat, son åt Afiah, son åt ein benjaminit. Han var ein velhalden mann.',
        2: 'Han hadde ein son som heitte Saul: velvaksen og væn; ingen i Israel var vænare enn han; han var hovudet høgre enn alt folket.',
        3: 'No hadde nokre asnor komne burt for Kis, far åt Saul. Og Kis sagde med Saul, son sin: «Tak med deg ein av drengjerne, og far av stad og leita etter asnorne!»',
        4: 'Han gjekk yver Efraimsheidi og so gjenom Salisalandet; men han fann deim ikkje. So gjekk dei gjenom Sa’alimslandet; men dei var ikkje der. So gjekk dei gjenom Benjaminslandet, men fann deim ikkje.',
        5: 'Då dei so var komne inn i Suflandet, sagde Saul med drengen han hadde med seg: «Kom, lat oss venda heim att; elles vil far verta illhuga for oss i staden for å tenkja på asnorne.»',
        6: 'Men han svara honom: «Sjå her i byen er det ein gudsmann som er namngjeten; alt det han segjer, det hender. Lat oss no ganga dit. Kann henda han kunde fortelja oss noko um den ferdi me hev gjeve oss ut på.»',
        7: 'Saul sagde til drengen: «Men um me no gjeng dit, kva skal me hava med oss til mannen? Me hev ikkje meir mat i skrepporne våre, og nokor onnor gåva hev me ikkje heller til gudsmannen; eller kva hev me?»',
        8: 'Drengen svara Saul andre venda: «Sjå, her hev eg i mitt eige ein kvart dalar i sylv; den vil eg gjeva gudsmannen, so han segjer oss kva leid me bør taka.»',
        9: 'Fyrr i tidi pla dei segja i Israel når einkvan gjekk av stad og spurde Gud: «Kom, lat oss ganga til sjåaren!» Det dei no kallar profet, kalla dei i gamle dagar sjåar.',
        10: 'Saul sagde til drengen: «Du hev rett! kom, lat oss ganga!» So gjekk dei til byen der gudsmannen budde.',
        11: 'Då dei gjekk upp bykleivi, møtte dei nokre gjentor som gjekk ut, skulde henta vatn, og spurde deim: «Er sjåaren her?»',
        12: 'Dei svara deim: «Ja, beint her burte. Skunda deg no! han kom nett heim til byen i dag; for i dag hev folket slagtoffer på offerhaugen.',
        13: 'Når de gjeng inn i byen, so finn de honom fyrr han gjeng upp på offerhaugen til måltidi; folket held ikkje måltid fyrr han kjem; for han skal vigsla offeret fyrr gjesterne tek til å eta. Gakk difor straks! nett no finn de honom.»',
        14: 'Dei gjekk upp til byen. Nett med same dei kom inn i byen, møtte dei Samuel på veg upp til offerhaugen.',
        15: 'Dagen fyrr Saul kom, hadde Herren opna øyra åt Samuel og sagt til honom:',
        16: '«I morgon dette bil sender eg til deg ein mann frå Benjaminslandet; honom skal du salva til fyrste yver Israel, folket mitt; han skal frelsa folket mitt frå filistarmagti. Eg hev set til folket mitt, etter di naudropet deira hev nått upp til meg.»',
        17: 'Då Samuel fekk sjå Saul, gjorde Herren kunnigt for honom: «Sjå her er mannen som eg tala um til deg; han skal taka herredømet yver folket mitt.»',
        18: 'Saul gjekk fram til Samuel midt i porten og sagde: «Ver so snild og seg meg; kvar bur sjåaren!»',
        19: 'Samuel svara Saul: «Eg er sjåaren. Gakk i fyrevegen upp på offerhaugen! De skal eta med meg i dag. I morgon tidleg, når eg segjer farvel med deg, skal eg gjeva deg greida på alt det du hev på hjarta.',
        20: 'Asnorne som kom burt i dag tri dagar sidan, tarv du ikkje vera rædd for; dei er attfunne. Kven er det elles som eig alle eignaluter i Israel, anna du og farsætti di?»',
        21: 'Saul svara: «Er ikkje eg benjaminit, av den minste ætti i Israel? og mi ættgrein er den ringaste av alle Benjamins-ætterne. Kvifor talar du soleis med meg?»',
        22: 'Samuel tok då Saul og drengen hans og leidde deim inn i gildesalen og sessa deim øvst millom gjesterne; dei var um lag tretti mann.',
        23: 'Og Samuel sagde til kokken: «Kom hit med det stykket eg gav deg og bad deg gøyma vel!»',
        24: 'Kokken bar fram lårstykket og det som høyrde til, og sette framfor Saul. Og han sagde: «Her er det som er gøymt åt deg. Et no! Til denne høgtidsstundi vart det gøymt åt deg då eg sagde: Eg hev bede folket.» Saul heldt då måltid med Samuel den dagen.',
        25: 'So gjekk dei ned frå offerhaugen og inn i byen, og han tala med Saul på taket.',
        26: 'Tidleg næste morgon då det lyste av dag, ropa Samuel på Saul uppe på taket: «Ris upp, so vil eg fylgja deg på veg!» Saul reis upp, og dei gjekk båe av stad, han og Samuel.',
        27: 'Då dei var komne utanfor byen, sagde Samuel med Saul: «Bed drengen ganga fyre oss!» - han so gjorde - men sjølv må du stogga eit bil, so skal du få høyra det Gud hev tala.',
    },
    10: {
        1: 'So tok Samuel oljeflaska og slo olje på hovudet hans, kysste honom og sagde: «No hev Herren salva deg til fyrste yver arvluten sin.',
        2: 'Når du gjeng frå meg, kjem du til å møta tvo menner attmed Rakel-gravi, ved landskilet mot Benjamin ved Selsah. Dei skal segja med deg: «Asnorne du leita etter, er attfunne; far din kjem difor ikkje i hug asnorne meir; men han er illhuga for dykk og segjer: «Kva skal eg gjera for son min?»»',
        3: 'Når du heldt fram derifrå og kjem til Taboreiki, vil du der møta tri menner som er på veg upp til Gud i Betel; ein med tri kid, ein med tri brødleivar og ein med ei vinhit.',
        4: 'Dei helsar deg heil og sæl og gjev deg tvo brød, og du skal taka imot det dei gjev deg.',
        5: 'Deretter kjem du til Guds Gibea, der som filistarvakti held seg. Og når du kjem inn der i byen, råkar du på ein profetflokk som kjem ned frå offerhaugen i profetisk eldhug med harpa, trumma, fløyta og cither.',
        6: 'Og Herrens ande skal koma yver deg, so du og kjem i profetisk uppgløding liksom dei. Og du skal verta ein annan mann.',
        7: 'Når du ser desse jarteigner ovra seg, so må du gjera det som fyre fell; for Gud er med deg.',
        8: 'So må du ganga ned fyre meg til Gilgal; og der skal eg koma ned til deg og ofra brennoffer og takkoffer. Sju dagar skal du drygja, til dess eg kjem og segjer deg kva du skal gjera.»',
        9: 'Då han no vende seg og gjekk frå Samuel; let Gud honom få ein annan hug. Og alle desse jartegnerne kom, same dagen.',
        10: 'Då dei kom til Gibea, møtte han ein profetflokk, og Guds ande kom yver honom, so han kom i profetisk eldhug midt imillom deim.',
        11: 'Då no alle som kjende honom frå fyrr, fekk sjå honom i profetisk eldhug liksom profetarne, sagde dei seg imillom: «Kva er det som kjem åt son til Kis? Er Saul og millom profetarne?»',
        12: 'Ein mann der i grendi svara: «Kven er då deira far?» Av dette kom det ordtaket: «Er Saul og millom profetarne?»',
        13: 'Då eldhugen seig av honom, gjekk han upp på offerhaugen.',
        14: 'Då spurde farbror åt Saul honom og drengen hans: «Kvar hev de vore?» Han svara: «På leit etter asnorne. Då me såg dei ingen stad var å finna, kom me til Samuel.»',
        15: 'Farbroren sagde: «Fortel meg kva Samuel sagde med dykk!»',
        16: 'Saul svara: «Han sagde med oss at asnorne var attfunne.» Men det Samuel hadde sagt um kongedømet, nemnde han ikkje med honom.',
        17: 'Samuel stemnde folket saman til Herren i Mispa.',
        18: 'Og han sagde til Israels-borni: «So segjer Herren, Israels Gud: «Eg hev ført Israel upp frå Egyptarland, eg frelste dykk frå egyptarmagti og frå alle dei kongeriki som trengde dykk.',
        19: 'Men no hev de vanda dykkar Gud, som frelste dykk ut or alle ulukkor og trengslor, og det segjer til honom: «Set ein konge yver oss!» So stig då fram for Herren etter dykkar ættar og ættgreiner.»»',
        20: 'So let Samuel alle Israels ætter stiga fram. Luten fall på Benjamins-ætti.',
        21: 'Då so Benjamins-ætti gjekk fram etter ættgreinerne sine, fall luten på Matri-greini; so fall han på Saul, Kis-sonen. Men då dei leita etter honom, var han ikkje å finna.',
        22: 'Dei spurde då Herren ei venda til: «Er det endå ein mann her?» Herren svara: «Han hev løynt seg millom ferdagodset.»',
        23: 'Dei sprang dit og henta honom. Og då han steig fram millom folket, var han hovudet høgre enn alle dei hine.',
        24: 'Samuel sagde til folket: «Her ser de den som Herren hev valt ut; det finst ingen maken hans i heile folket.» Då sette heile folket i med fagnadrop: «Live kongen!»',
        25: 'Samuel kunngjorde folket kongelovi, og rita henne i ei bok, som han lagde ned framfor Herren. So let Samuel heile folket fara heim att.',
        26: 'Saul gjekk ogso heim til Gibea. Og med honom fylgde ein flokk djerve karar, som var gripne i hjarta av Gud.',
        27: 'Men nokre illmenne sagde: «Kva hjelp kann denne mannen gjeva oss?» Dei vanvyrde honom og bar ingi hyllingsgåva til honom. Men han læst som han inkje gådde.',
    },
    11: {
        1: 'Ammoniten Nahas drog upp og kringsette Jabes i Gilead. Då sagde alle Jabes-buarne med Nahas: «Gjer forlik med oss, so skal me tena deg!»',
        2: 'Men ammoniten Nahas svara deim: «Ja, på det vilkåret gjer eg forlik med dykk, at eg sting ut høgre auga på dykk alle, til skjemsla for heile Israel.»',
        3: 'Styresmennerne i Jabes sagde til honom: «Gjev oss sju dagar frest, so me fær skikka bod yver heile Israelsriket. Er det so ingen som bergar oss, so skal me gjeva oss yver til deg.»',
        4: 'Då sendebodi kom til Sauls Gibea og lagde fram saki fram for folket, brast heile folket i gråt.',
        5: 'Saul kom nett heim frå åkeren attum uksarne. Han spør: «Kva hev kome åt folket, etter di dei græt?» Dei fortalde honom det som Jabes-buarne hadde sagt.',
        6: 'Då Saul høyrde dette, kom Guds ande yver honom; harmen loga upp i honom;',
        7: 'og han tok tvo uksar, lema deim sund og sende stykki rundt i heile Israelsriket med sendebod som sagde: «Den som ikkje fylgjer Saul og Samuel, hans uksar skal fara soleis.» Ei rædsla frå Herren fall på heile folket. Og ut drog dei, alle som ein.',
        8: 'Han mynstra heren i Bezek; Israels-sønerne talde tri hundrad tusund, og Juda-folki tretti tusund.',
        9: 'Dei sagde med sendemennerne som var komne: «So skal det segja med Jabes-buarne i Gilead: «I morgon ved høgstedags leite skal de få hjelp!»» Då sendemennerne kom heim og fortalde det til Jabes-buarne, vart dei glade.',
        10: 'Og dei sagde til Nahas: «I morgon skal me gjeva oss yver til dykk; då fær de gjera med oss som de tykkjer.»',
        11: 'Morgonen etter skifte Saul folket i tri flokkar. Og dei braut seg inn i lægret fyrstundes i otta, og hogg ned ammonitarne frå morgonen til høgstedags leite. Dei som slapp undan, vart spreidde til alle kantar, so det vart ikkje att tvo i lag.',
        12: 'Då sagde folket med Samuel: «Kven var det som sagde: «Skal Saul vera konge yver oss?» Lat oss få tak i dei kararne, so vil me drepa deim.»',
        13: 'Men Saul sagde: «Ingen skal drepast i dag. For i dag hev Herren gjeve Israel siger.»',
        14: 'Og Samuel sagde med folket: «Kom, lat oss ganga til Gilgal og nya upp kongedømet der!»',
        15: 'Og heile folket gjekk til Gilgal, og gjorde Saul til konge der framfor Herren i Gilgal, og ofra takkoffer framfor Herren. Og alle Israels-mennerne gledde seg med ovstor fagnad.',
    },
    12: {
        1: 'Samuel sagde til heile Israel: «Sjå, eg hev lydt dykk i alt de hev kravt av meg. Eg hev sett ein konge yver dykk.',
        2: 'No heretter vil kongen verta styraren dykkar. Eg er gamall og grå, og sønerne mine er hjå dykk. Frå ungdomsåri til i dag hev eg vore styraren dykkar.',
        3: 'Sjå her stend eg! Vitna no mot meg, so Herren og den han salva høyrer på: Hev eg teke ein ukse frå nokon? eller hev eg teke eit asen frå nokon? hev eg trælka nokon? eller trakka på nokon? hev eg teke mutor av nokon, so eg skulde sjå gjenom fingrarne med honom? So vil eg gjeva dykk vederlag.»',
        4: 'Dei svara: «Ikkje hev du trælka oss, og ikkje trakka på oss, og ingen ting hev du teke frå nokon mann.»',
        5: 'Då sagde han til deim: «So er Herren vitne mot dykk, og den han salva er vitne i dag, at de ingen ting hev funne å krevja hjå meg.» Dei svara ja.',
        6: 'Samuel sagde til folket: «Herren er vitne, han som vekte upp Moses og Aron, og som førde federne dykkar upp frå Egyptarland.',
        7: 'Stig no fram! so vil eg gjera upp med dykk framfor Herren for alle Guds vise verk, som han hev gjort mot dykk og mot federne dykkar.',
        8: 'Då Jakob var komen til Egyptarland, ropa federne dykkar til Herren. Og Herren sende Moses og Aron og førde federne dykkar ut or Egyptarland og gav deim bustad her i landet.',
        9: 'Men dei gløymde Herren, sin Gud, og han gav deim i henderne på Sisera, herhovdingen i Hasor, og i henderne på filistarane og på Moab-kongen; og dei gjekk i strid mot deim.',
        10: 'So ropa dei til Herren og sagde: «Me hev synda; for me hev svike Herren og tent Ba’als-bilæti og Astarte-bilæti; men frels oss no frå fiendarne våre, so vil me tena deg.»',
        11: 'So sende Herren Jerubba’al og Bedan og Jefta og Samuel, og frelste dykk frå fiendarne dykkar på alle kantar, so de fekk bu trygt.',
        12: 'Men då de såg Nahas, ammonitarkongen, kom yver dykk, so sagde de til meg: «Nei, ein konge vil me hava til styrar yver oss» - endå Herren, dykkar Gud, var kongen dykkar.',
        13: 'Og no - her stend kongen som de hev kåra, den det hev kravt. Herren hev sett ein konge yver dykk.',
        14: 'Berre de no vil bera age for Herren og tena honom og lyda honom, og ikkje setja dykk upp mot Herrens bod, men fylgja Herren, dykkar Gud, både de og kongen som hev vorte styraren dykkar!',
        15: 'Lyder de ikkje Herren, men set de dykk upp mot Herrens bod, då vil Herrens hand vera imot dykk liksom mot federne dykkar.',
        16: 'Stig no fram og skoda dette store underet som Herren vil gjera beint framfor augo dykkar!',
        17: 'No er det tidi for kveiteskurden, veit det. Men eg vil ropa til Herren, at han sender tora og regn. Soleis skal de skyna og sjå kor stor ei synd det er i Herrens augo, det de gjorde då de kravde ein konge.»',
        18: 'Samuel ropa til Herren. Og Herren sende torever og regn den dagen. Då fekk heile folket stor age for Herren og for Samuel.',
        19: 'Og heile folket sagde til Samuel: «Bed til Herren for tenarane dine, so me ikkje skal døy, for di me hev auka synderne våre med den misgjerningi at me kravde ein konge!»',
        20: 'Samuel sagde til folket: «Ver ikkje rædde! Visst hev de gjort alt dette vonde. Men fall berre ikkje frå Herren no! men ten Herren av all dykkar hug!',
        21: 'Fall ikkje frå! for då kjem de til å fara etter tome avgudar, som ingen gagnar og ingen fagnar; tome er dei.',
        22: 'Herren skal taka folket sitt til nåde, for sitt store namn skuld, etter di det tektest Herren å gjera dykk til sitt folk.',
        23: 'Og eg for meg: aldri i verdi vil eg synda mot Herren med å slutta å beda for dykk. Nei, eg vil læra dykk den gode og rette vegen.',
        24: 'Berre de vil bera age for Herren og ten honom truleg av all dykkar hug! For sjå kor store ting han hev gjort for dykk!',
        25: 'Men gjer de det som vondt er, so er det ute både med dykk og kongen dykkar.»',
    },
    13: {
        1: 'Saul hadde vore konge eitt år. Andre året han var konge yver Israel,',
        2: 'valde han seg ut or Israel tri tusund mann. Av desse hadde Saul hjå seg tvo tusund i Mikmas og i Betelsfjellbygdii, og eitt tusund hadde Jonatan med seg i Gibea i Benjamin. Resten av krigsfolket sende han heim kvar til seg.',
        3: 'Jonatan slo i hel filistarvakti i Gibea, og filistarane høyrde gjete det. Men Saul let blåsa i lur yver heile landet og sagde: «Hebræarane må høyra det.»',
        4: 'Heile Israel fekk høyra at Saul hadde slege i hel filistarvakti, og at Israel hadde fenge uord på seg hjå filistarane for det same. Folket vart då utbode til å fylgja Saul til Gilgal.',
        5: 'Filistarane stemnde saman til krig mot Israel, tri tusund vogner og seks tusund hestfolk, og fotfolk so mange som sanden på havsens strand. Dei drog upp og lægra seg ved Mikmas austanfor Bet-Aven.',
        6: 'Då Israels-mennerne såg dei var komne i knipa, av di filistarane trengde på, so for folket av og løynde seg i hellerar, i klungerkjørr, i gil, i kjellarar og brunnar.',
        7: 'Og hebræararne hadde fare yver Jordan, til Gadslandet og Gileadslandet. Saul var endå i Gilgal, og heile folket fylgde honom skjelvande.',
        8: 'Han drygde sju dagar, til den tid Samuel hadde fastsett. Men då Samuel endå ikkje var komen til Gilgal, og då folket tok til å spreida seg og ganga frå honom,',
        9: 'sagde Saul: «Kom hit til meg med brennofferet og takkofferet!» Og so bar han fram brennofferet.',
        10: 'Nett med same han det hadde gjort, då kom Samuel. Saul møtte honom og vilde helsa honom.',
        11: 'Men Samuel sagde: «Kva er det du hev gjort?» Saul svara: «Då eg såg folket tok til å spreida seg og ganga frå meg, og du ikkje var komen til fastsett tid, og filistarane hadde samla seg i Mikmas,',
        12: 'so tenkte eg: «No kjem filistarane yver meg i Gilgal, og eg hev endå ikkje blidka Herren.» So våga eg meg til å bera fram brennofferet.»',
        13: 'Samuel sagde til Saul: «Du var uvisleg gjort av deg. Hadde du agta på bodet frå Herren, din Gud, som han baud deg, so vilde Herren no ha grunnfest kongedømet ditt til æveleg tid.',
        14: 'Men no vil kongedømet ditt ikkje standa seg. Herren hev valt seg ut ein mann etter sin hug; og Herren hev etla honom til fyrste yver folket sitt, av di du ikkje agta på det Herren baud deg.»',
        15: 'Samuel reis upp og for heim frå Gilgal upp til Benjamins Gibea. Saul mynstra krigsfolket som var hjå honom; um lag seks hundrad mann.',
        16: 'Saul og Jonatan heldt seg i Geba i Benjamin med det folket som var att hjå deim, og filistarane låg i læger i Mikmas.',
        17: 'Frå filistarlægret sende dei ut røvarflokkar i tri hopar; eine hopen tok vegen til Ofra i Sualslandet,',
        18: 'andre hopen tok vegen til Bet-Horon, og tridje hopen tok vegen til kverven som hallar ned imot Sebojimsdalen, burtimot øydemarki.',
        19: 'Det fanst ingen smed i heile Israelslandet; for filistarane hadde vore rædde at hebræarane skulde smida sverd eller spjot.',
        20: 'Og so laut kvar einast israelit ned til filistarane og få kvest både plogjarn og grev og øksar og ristlar,',
        21: 'so snart eggjarne vart skjemde på plogjarni, eller grevi, eller greiparne, eller øksarne, eller når dei turvte vøla på oksebroddarne.',
        22: 'Av dette hadde det seg so at då slaget skulde standa, hadde ingen av mennerne åt Saul og Jonatan sverd eller spjot. Einast Saul og Jonatan, son hans hadde våpn.',
        23: 'Filistarane sette fram ein utpost i Mikmasskardet.',
    },
    14: {
        1: 'Det bar so til ein dag at Jonatan, Saulssonen, sagde med våpnsveinen sin: «Kom, lat oss ganga yver til filistarutposten der burte på hi sida!» Men han gat det ikkje med far sin.',
        2: 'Saul heldt seg i utkanten av Gibea under granatapallen i Migron, og folket han hadde med seg, var um lag seks hundrad mann.',
        3: 'Ahia Ahitubsson, bror åt I-kabod, son åt Pinehas Elison, Herrens prest i Silo, han bar no messehakelen. Og folket visste ikkje at Jonatan var gjengen.',
        4: 'I skardet der Jonatan freista ganga yver til filistarutposten, låg ein berghamar på kvar sida; den eine heitte Boses, og den andre Sene.',
        5: 'Den eine hamaren reis upp mot nord, beint imot Mikmas, den andre mot sør, beint imot Geba.',
        6: 'Jonatan sagde med våpnsveinen sin: «Kom, lat oss klyva yver til utposten åt desse u-umskorne! kann henda vil Herren hjelpa oss. Det er ingen ting i vegen for at Herren kann gjeva siger anten dei er få eller mange.»',
        7: 'Våpnsveinen svara: «Gjer alt det du tykkjer! Berre gakk på! eg fylgjer deg kvar du vil.»',
        8: 'Jonatan sagde: «Me kliv yver til dei kararne, og lager det so at dei ser oss.',
        9: 'Segjer dei då: «Stana der til dess me kjem burt åt dykk!» so stoggar me der me stend, og gjeng ikkje upp til deim.',
        10: 'Men segjer dei: «Kom hit upp til oss!» då gjeng me upp; for då hev Herren hev gjeve deim i våre hender. Det skal me hava til jarteign.»',
        11: 'Då no båe filistarutposten fekk sjå dei tvo, sagde dei: «Sjå hebræarane kryp ut or holorne der dei hev løynt seg.»',
        12: 'Og utpostkararne ropa til Jonatan og våpnsveinen hans: «Kom hit upp til oss, so skal de få full greida!» Jonatan sagde med våpnsveinen: «Fylg meg! Herren hev gjeve deim i Israels hand.»',
        13: 'Jonatan kleiv uppetter på hender og føter, og våpnsveinen fylgde. Jonatan felte deim, og våpnsveinen fylgde etter og gjorde det av med deim.',
        14: 'I fyrste åtaket Jonatan og våpnsveinen gjorde, hogg dei ned um lag eit tjug, på ei vidd som ein halv dags plogland.',
        15: 'Då vart dei fjetra både i lægret og på marki heile heren; og utpostarne og røvarflokkarne vart og fjetra. Og grunnen skalv, so det kom ein støkk frå Gud yver deim.',
        16: 'Vaktpostarne åt Saul i Gibea i Benjamin såg at heile hopen var reint i ørska, so dei vingla i kross og krok.',
        17: 'Saul sagde til krigsfolket sitt; «Mynstra heren, og sjå kven som vantar!» Dei mynstra heren, og fekk sjå at Jonatan og våpnsveinen hans vanta.',
        18: 'Då sagde Saul til Ahia: «Kom hit med Guds kista!» For Guds kista var den tid millom Israels-borni.',
        19: 'Men medan Saul tala med presten, auka ståket i filistarlægret allstødt. Saul sagde då til presten: «Det kann vera det same.»',
        20: 'So samla dei seg på slagmarki, Saul og alt krigsfolket hans, og fekk sjå fiendarne lyfte sverdi mot kvarandre, og dei var so forstøkte, at dei visste korkje att eller fram.',
        21: 'Dei hebræarane som frå gamalt hadde vore i filistarmagt, og hadde fylgt med deim upp og var spreidde rundt i lægret, dei og slo lag med Israels-heren under Saul og Jonatan.',
        22: 'Og då dei Israels-mennerne som hadde løynt seg i Efraimsfjellbygdi, høyrde gjete at filistarane var på flog, sette alle dei og etter deim og kom med i slaget.',
        23: 'Soleis gav Herren Israel siger den dagen. Og bardagen flutte seg heilt framum Bet-Aven.',
        24: 'Det røynde hardt på kvar israelit den dagen. Og Saul batt folket med denne eiden: «Forbanna den som et noko mat fyre kvelden, fyrr eg hev teke hemn yver fiendarne mine!» So var det ingen som smaka matbiten.',
        25: 'Då dei alle i hop kom inn i skogen, låg det honning på marki.',
        26: 'Men då folket kom upp i skogen og fekk sjå honning strøyma ut, våga ingen føra handi til munnen, av age for eiden.',
        27: 'Jonatan hadde ikkje lydt på då far hans tok folket i eid; difor rette han ut staven han hadde i handi og duppa den eine enden i honningen, og førde so handi til munnen; han vart då bjartøygd att.',
        28: 'Ein av mennerne tok til ords og sagde: «Far din hev bunde folket med denne eiden: «Forbanna kvar den som et noko mat i dag!» - endå dei var trøytte.»',
        29: 'Jonatan svara: «Far fører ulukka yver landet! Sjå, kor augo mine ljosna av di eg smaka noko lite på denne honningen.',
        30: 'Kor mykje større mannefall skulde det ikkje vorte millom filistarane um mennerne hadde fenge eta seg mette i dag av herfanget dei vann hjå fiendarne sine!»',
        31: 'Like vel: dei slo filistarane den dagen og forfylgde deim frå Mikmas til Ajjalon, og folki var svært trøytte.',
        32: 'So kasta folket seg yver herfanget, tok sauer og uksar og kalvar, og slagta deim på marki, og åt kjøtet med blodet i.',
        33: 'Dei melde det åt Saul og sagde: «Sjå, folket syndar mot Herren og et kjøt med blod i.» Då ropa Saul: «De hev gjort svik! Velt ein stor stein hit til meg!»',
        34: 'Og Saul sagde: «Gakk ut millom folket og seg til deim: «Kvar og ein skal føra hit til meg uksen sin og sauen sin og slagta og eta honom her! Ikkje må de synda mot Herren og eta kjøt med blod i!»» Då førde heile folket fram um natti, kvar med eigi hand, uksarne sine, og slagta deim der.',
        35: 'Saul bygde eit altar for Herren. Dette var det fyrste altaret han bygde åt Herren.',
        36: 'Og Saul sagde: «Lat oss forfylgja filistarane i natt og herja millom deim, alt til det dagast i morgon, so ingen av deim kjem undan!» Dei svara: «Gjer alt det du tykkjer!» Men presten sagde: «Lat oss ganga fram for Guds åsyn her!»',
        37: 'Då spurde Saul Gud: «Skal eg forfylgja filistarane? Vil du gjeva deim i Israels hand?» Men han gav deim ikkje svar den dagen.',
        38: 'Då sagde Saul: «Kom hit fram alle dei gjævaste av folket! so fær det sjå og gå kva det er for ei syndi som er gjord i dag.',
        39: 'So sant Herren liver, han som hev gjeve Israel siger, um det so er Jonatan, son min, skal han lata livet!» Ingen av folket svara honom.',
        40: 'Då sagde han til heile Israel: «Statt de på den eine sida, so vil eg med Jonatan, son min, standa på hi.» Folket svara Saul: «Gjer som du tykkjer!»',
        41: 'Då sagde Saul til Herren, Israels Gud: «Lat sanningi koma for dagen!» Då fall luten på Jonatan og Saul, og folket gjekk fritt.',
        42: 'Saul sagde: «Drag strå millom meg og Jonatan, son min!» Då fall luten på Jonatan.',
        43: 'Saul sagde til Jonatan: «Seg meg kva du hev gjort!» Då sagde Jonatan det med honom: «Med enden av staven eg hadde i handi, tok eg noko lite honning og smaka lite grand på det. Sjå her er eg, ferdig til å døy.»',
        44: 'Saul svara: «Ja, Gud late meg bøta for det no og sidan! Livet lyt du lata, Jonatan!»',
        45: 'Men folket sagde til Saul: «Skulde Jonatan døy? Han som hev vunne denne store sigeren for Israel! Aldri i verdi! So sant Herren liver, ikkje eit hår på hovudet hans skal vert skadt! for med Guds hjelp hev han gjort dette i dag.» Og folket løyste Jonatan ut; han vart ikkje drepen.',
        46: 'Saul drog heim, og forfylgde ikkje filistarane meir. Filistarane drog og heim til seg.',
        47: 'Då Saul hadde eigna til seg kongedømet i Israel, førde han krig mot alle fiendarne sine rundt ikring: Moab, ammonitarne, Edom, kongarne i Soba og filistarane. Og kvar helst han vende seg, tukta han deim.',
        48: 'Han vann seg stort velde. Han slo Amalek - og fria soleis Israel frå deim som herja det.',
        49: 'Sønerne åt Saul var Jonatan, Jisvi og Malkisua. Av dei tvo døtterne hans heitte den eldste Merab og den yngste Mikal.',
        50: 'Kona åt Saul heitte Ahinoam Ahima’asdotter. Hovdingen yver heren hans heitte Abner, son åt Ner, som var farbror åt Saul;',
        51: 'for Kis, Sauls far, og Ner, Abners far, var søner åt Abiel.',
        52: 'Krigen mot filistarane var allstødt hard so lenge Saul livde. Og so tidt Saul såg ei kjempa eller ein dugande kar, tok han honom i si tenesta.',
    },
    15: {
        1: 'Samuel sagde til Saul: «Det var meg Herren sende til å salva deg til konge yver Israel, folket sitt. So lyd no Herrens ord!',
        2: 'So hev Herren, allhers drott, sagt: «Eg vil hemna det Amalek gjorde mot Israel med di han lagde seg i vegen for deim då dei drog upp frå Egyptarland.',
        3: 'Gakk no ut og vinn yver amalekitarne! Du skal bannstøytte deim og alt det dei eig. Du skal ikkje tykkja synd i deim, men drepa både kar og kvende, småborn og sogborn, bu og smale, kamelar og asen.»»',
        4: 'So baud Saul ut herfolket og mynstra deim i Telajim; tvo hundrad tusund mann fotfolk og dessutan ti tusund mann frå Juda.',
        5: 'Då Saul kom til Amalekbyen, sette han umsåtmenner i dalen.',
        6: 'Saul sagde til kenitarne: «Kom, skil dykk ut! Far undan frå amalekitarne, so eg ikkje skal gjera ende på dykk samstundes med deim! De synte då godhug mot alle Israels-borni då dei drog upp frå Egyptarlandet.» Då skilde kenitarne seg frå amalekitarne.',
        7: 'Saul vann yver amalekitarne og forfylgde deim frå Havila til fram imot Sur, som ligg austan for Egyptarland.',
        8: 'Han tok Agag, amalekitarkongen, livande til fange; og alt folket bannstøytte han og hogg deim ned.',
        9: 'Men Saul og folket sparde Agag og det beste og det næstbeste av smalen og bufeet og lambi, alt som hadde verde; sovore vilde dei ikkje bannstøyta. Men alt skrapfeet og alle skrantne dyr, deim bannstøytte dei.',
        10: 'Herrens ord kom til Samuel:',
        11: '«Eg angrar at eg gjorde Saul til konge! Han hev vendt seg burt frå meg og ikkje gjort det eg sette honom til.» Då harmast Samuel, og han ropa til Herren heile natti.',
        12: 'Då Samuel reis upp tidleg um morgonen og gjekk til møtes med Saul, fekk han høyre gjete: «Saul hev fare til Karmel og reist seg eit æreminne der; so hev han snutt heim att og fare ned att til Gilgal.»',
        13: 'Då Samuel kom til Saul, sagde Saul til honom: «Velsigna vere du av Herren! No hev eg gjort det Herren sette meg til.»',
        14: 'Samuel svara: «Kva er det for bræking som læt for øyro mine? Kva er det for rauting eg høyrer?»',
        15: 'Saul sagde: «Frå amalekitarne hev dei ført deim hit. Folket sparde det beste av bufe og smale til slagtoffer åt Herren, din Gud. Resten bannstøytte me.»',
        16: 'Samuel sagde til Saul: «Teg still! so vil eg kunngjera deg kva Herren hev sagt meg i natt.» Han sagde til honom: «Seg det!»',
        17: 'Samuel sagde: «Du veit du vart hovding yver Israels-ætterne, då du tyktest deg sjølv ring. For Herren salva deg til konge yver Israel.',
        18: 'Og Herren sende deg av stad og sagde: «Gakk og bannstøyt desse syndarar amalekitarne! Før krig mot deim, til dess du hev tynt deim!»',
        19: 'Kvifor lydde du ikkje Herren, men kasta deg yver herfanget og gjorde det som Herren mislikar?»',
        20: 'Saul svara Samuel: «Eg hev lydt Herren og gjenge vegen Herren sende meg. Eg hev ført Agag, amalekitarkongen, hit, og amalekitarne hev eg bannstøytt.',
        21: 'Men folket tok av herfanget bufe og smale, det beste av det bannstøytte, til offer for Herren, din Gud, i Gilgal.»',
        22: 'Då sagde Samuel: «Meiner du Herren hev hugnad i brennoffer og slagtoffer likso mykje som i lydnad mot Herren? Nei, lydnad er betre enn likaste offeret, ope øyra betre enn feitaste veren.',
        23: 'Trass er trollskap, einvisa er som avgudar og husgudar. Av di du vanda Herrens ord, hev han vanda deg, so du vert ikkje kanna konge lenger.»',
        24: 'Saul sagde til Samuel: «Eg hev synda med di eg hev gjorde tvert imot det Herren baud meg og du tala til meg. Folket var eg rædd og gjorde deim til viljes.',
        25: 'Men tilgjev no det eg hev synda! Ver med meg heim, so eg kann bøygja kne for Herren!»',
        26: 'Samuel sagde til Saul: «Eg vil ikkje vera med deg heim. Av di du hev vanda Herrens ord, hev Herren vanda deg, so du skal ikkje vera konge yver Israel.»',
        27: 'Då no Samuel snudde seg og vilde ganga, tok han tak i snippen på kappa hans, og reiv honom av.',
        28: 'Då sagde Samuel til honom: «Herren hev i dag rive kongedømet yver Israel frå deg og gjeve det åt ein annan som er betre enn du.',
        29: 'Israels heider lyg ikkje og angrar ikkje. For ikkje eit menneskje er han, so han skulde angra.»',
        30: 'Han svara: «Eg hev synda. Men syn meg no den æra framfor dei øvste i folket mitt og heile Israel, at du er med meg heim, so eg kann bøygja kne for Herren, din Gud.»',
        31: 'So fylgde Samuel med Saul, og Saul bøygde på kne for Herren.',
        32: 'Samuel sagde: «Før hit til meg Agag, amalekitarkongen!» Då gjekk Agag fram til honom med lystig hug, med di han sagde: «Visst er det beiske i dauden burte!»',
        33: 'Men Samuel sagde: «Liksom ditt sverd hev gjort kvinnor barnlause, soleis skal di mor verta barnlaus meir enn andre kvinnor.» Og Samuel gav Agag banehogg framfor Herren i Gilgal.',
        34: 'Samuel gjekk til Rama, og Saul for heim att til Sauls Gibea.',
        35: 'Samuel vilde ikkje sjå Saul meir so lenge han livde. For Samuel syrgde yver Saul, av di Herren angra han hadde gjort Saul til konge yver Israel.',
    },
    16: {
        1: 'Herren sagde til Samuel: «Kor lenge etlar du å syrgja yver Saul? Eg hev då vanda honom, so han skal ikkje vera konge yver Israel. Fyll hornet ditt med olje og gakk av stad! Eg vil senda deg til Isai i Betlehem. Ein av sønerne hans hev eg etla til konge.»',
        2: 'Samuel sagde: «Kor kann eg ganga dit? Fær Saul fretta det, drep han meg.» Herren svara: «Tak ei kviga med deg, so kann du segja: «Eg er komen og vil ofra til Herren.»',
        3: 'So skal du beda Isai til offermåltidi, so skal eg lata deg vita det du skal gjera; og du skal salva åt meg den eg segjer.»',
        4: 'Samuel gjorde som Herren sagde: Då han kom til Betlehem, kom dei øvste i byen skjelvande imot honom og spurde: «Varslar det godt at du kjem?»',
        5: 'Han svara: «Ja, eg kjem og vil ofra til Herren. Det lyt helga dykk, so det kann vera med meg ved offermåltidi!» Og han helga Isai og sønerne hans og bad deim vera med ved offermåltidi.',
        6: 'Då dei kom, og han fekk sjå Eliab, tenkte han: «Der stend visst framfor Herren den han salvar.»',
        7: 'Men Herren sagde til Samuel: «Skoda ikkje på kor han ser ut, kor stor og høg han er på vokster; for honom vil eg ikkje hava. Det munar ikkje det menneskja ser; menneskja ser på utsyni, men Herren ser på hjarta.»',
        8: 'Då kalla Isai på Abinadab og let honom ganga fram for Samuel. Men han sagde: «Heller ikkje denne hev Herren valt seg ut.»',
        9: 'Isai let Samma ganga fram. Men han sagde: «Heller ikkje denne hev Herren valt.»',
        10: 'Isai sju av sønerne ganga fram for Samuel. Men Samuel sagde til Isai: «Herren hev ikkje valt ut nokon av desse.»',
        11: '«Er dette alle gutarne dine?» spurde han Isai. Han svara: «Endå er den yngste att. Men han gjæter smalen.» «Send bod etter honom!» sagde Samuel med Isai; «for me vil ikkje setja oss til bords fyrr han kjem hit.»',
        12: 'Då sende han bod etter honom. Han var raudleitt, hadde bjarte øugo, og var væn å sjå til. Og Herren sagde: «Ris upp og salva honom; han er det!»',
        13: 'Då tok Samuel oljehornet og salva honom, so brørne hans såg på. Og Herrens Ande kom yver David frå den dagen og sidan. So stod Samuel upp og drog til Rama.',
        14: 'Etter Herrens Ande hadde vike frå Saul, kom det ei vond ånd frå Herren yver honom i brårider.',
        15: 'Tenarane åt Saul sagde med honom: «Sjå, du fær brårider av ei vond ånd frå Gud.',
        16: 'Herre, seg med tenarane dine som stend framfor deg, at dei leitar upp ein som kann leika på harpa! Når so den vonde åndi frå Gud kjem yver deg, kann han spela; då vil du besna.»',
        17: 'Saul sagde då med tenarane sine: «Sjå dykk ut for meg ein mann som er god til å spela, og få honom hit til meg!»',
        18: 'Ein av sveinarne svara: «Eg veit ein son åt Isai i Betlehem som kann spela, ein gjæv gut, våpndjerv, ordhag og fager. Herren er med honom.»',
        19: 'Saul sende då bod til Isai og bad honom: «Send hit til meg David, son din, han som er med smalen!»',
        20: 'Isai tok då og klyvja eit asen med mat, ei vinhit og eit kid og sende til Saul med David, son sin.',
        21: 'So kom David til Saul og vart tenaren hans. Han vart svært glad i honom og gjorde honom til våpnsveinen sin.',
        22: 'Og Saul sende bod til Isai og bad: «Kjære, lat David stogga hjå meg! for eg hev fenge godvilje for honom.»',
        23: 'So tidt åndi frå Gud kom yver Saul, so tok David harpa og leika på henne. Då letna det for Saul. Han besna, og den vonde åndi slepte honom.',
    },
    17: {
        1: 'Filistarane stemnde saman herarne sine til strid. Dei stemnde til Soko, som høyrer til Juda. Og dei lægra seg millom Soko og Azeka ved Efes-Dammim.',
        2: 'Saul og Israels hermenner hadde og samla seg, og lægra seg i Eikedalen. Dei fylkte seg til slag mot filistarane.',
        3: 'Filistarane stod på den eine fjellsida, Israels-mennerne på hi, med dalen midt imillom seg.',
        4: 'Då steig det fram frå filistarfylkingi ei einvigskjempa. Han var frå Gat, og heitte Goliat, var seks alner og ei spann høg.',
        5: 'Han hadde ein koparhjelm på hovudet, og gjekk med ei ringbrynja av kopar på fem tusund lodd.',
        6: 'Han hadde koparspenger på føterne, og bar eit koparspjot på ryggen.',
        7: 'Spjotskaftet var som ein vevbom, og jarnet på spjotodden vog seks hundrad lodd. Og våpnsveinen hans gjekk fyre honom.',
        8: 'Han steig no fram og ropa til Israels-fylkingi, og sagde til deim: «Kvifor dreg de ut og fylkjer dykk til slag? Er ikkje eg filistar? og de Sauls trælar? Vel dykk ein som kann koma hit ned til meg!',
        9: 'Magtast han slåst med meg og fella meg, so skal me vera dykkar trælar. Men vinn eg på honom og feller honom, so skal de vera våre trælar og tena oss.»',
        10: 'Filistaren ropa framleides: «No hev eg svivyrdt Israels-fylkingi. Send ein hit til meg, so me kann slåst!»',
        11: 'Då Saul og heile Israel høyrde desse ordi av filistaren, skalv dei og vart ovleg rædde.',
        12: 'David var son åt denne efratiten Isai som er nemnd, i Betlehem i Juda. Isai hadde åtte søner. På Sauls tid var han gamall og mykje til års komen.',
        13: 'Dei tri eldste sønerne åt Isai fylgde Saul i krigen. Desse tri sønerne hans som gjekk i krigen heitte: den eldste Eliab, den andre Abinadab, og den tridje Samma.',
        14: 'David var den yngste. Det var dei tri eldste som fylgde Saul.',
        15: 'Og David gjekk tidt heim frå Saul og gjætte smalen åt far sin i Betlehem.',
        16: 'Filistaren kom fram kvar morgon og kvar kveld i fyrti dagar.',
        17: 'Isai sagde med David, son sin: «Tak ei skjeppa av desse steikte aksi, og desse ti brødi, og skunda deg med deim til lægret til brørne dine!',
        18: 'Og desse ti osteskivorne skal du gjeva føraren. Du skal sjå um det stend vel til med brørne dine, og få ei kvitting av deim.',
        19: 'For Saul og dei og heile Israels-heren er i Eikedalen i krig med filistarane.»',
        20: 'Tidleg næste morgon reis David upp, let smalen åt ein hyrding, leste på seg og gjekk av stad, som Isai hadde bode honom. Han kom fram åt vognborgi, nett med same heren gjekk fram i fylking og lyfte herrop.',
        21: 'Dei stod no slagbudde både Israel og filistarane, fylking mot fylking.',
        22: 'David let trænvakti taka vare på føringi si, og sprang burt til heren. Han helsa på brørne sine, og spurde kor til stod.',
        23: 'Med han stod og tala med deim, fekk han sjå einvigskjempa, filistaren - Goliat heitte han, og var frå Gat - som kom fram or filistarfylkingi, og tok upp att dei vanlege ordi, so David høyrde det.',
        24: 'Alle Israels-mennerne rømde undan då dei såg honom, og var ovleg rædde.',
        25: 'Ein av Israels-mennerne sagde: «Ser de den karen som kjem fram der? Til svivyrding for Israel kjem han. Den som feller honom, vil kongen gjeva rikdom, og dotter si vil han gjeva honom, og ætti hans skal verta fri alle skattar og tyngslor i Israel.»',
        26: 'David spurde deim som stod attmed honom: «Kva fær den som feller denne filistaren og tek ei sovori svivyrding burt frå Israel? for kven er denne u-umskorne filistaren som vågar svivyrda fylkingarne åt den livande Gud?»',
        27: 'Folki tok upp att dei same ordi; Det og det vil den få som feller honom.',
        28: 'Då Eliab, eldste bror hans, høyrde kva han sagde med folki, vart han brennande harm på David. «Kva kjem du her etter?» ropa han. «Kven hev du late den vesle smaleflokken til burte i øydemarki? Eg veit du er ei vyrdløysa, og full av vondska. Du kjem berre og vil sjå på slaget.»',
        29: 'David sagde: «Kva hev eg då gjort? Det var då berre ein spurnad.»',
        30: 'So vende han seg frå honom mot ein annan og kom med same spursmålet; og han fekk same svaret som fyrr.',
        31: 'Men dei spurdest, desse ordi David hadde sagt. Og dei kom for øyro åt Saul, og han sende bod etter honom.',
        32: 'Og David sagde med Saul: «Ingen må missa modet. Tenaren din vil ganga imot denne filistaren og slåst med honom.»',
        33: 'Men Saul sagde til David: «Du er ikkje før til å ganga i strid mot denne filistaren. Du er berre ungguten, og han er stridsmann alt frå barneåri.»',
        34: 'David svara Saul: «Tenaren din hev gjætt smalen til far; kom då ei løva eller ein bjørn og røva ein sau i flokken,',
        35: 'so fylgde eg etter og drap udyret og reiv sauen ut or gapet på det. Um det reis upp på tvo imot meg, tok eg strupetak og gav det bane.',
        36: 'Hev no tenaren din felt både løva og bjørn, skal det ganga nett like eins med denne u-umskorne filistaren; for han hev svivyrdt fylkingarne åt den livande Gud.»',
        37: 'Og David sagde: «Herren som fria meg ut or klørne åt løva og bjørn, han vil fria meg frå denne filistaren.» Då sagde Saul med David: «Gakk! og Herren vil vera med deg.»',
        38: 'Saul klædde på David våpnkjolen sin, sette ein koparhjelm på hovudet hans og gav honom ei brynja.',
        39: 'Og David spente sverdet hans ikring seg utanpå våpnkjolen, og freista ganga soleis. Men han var ikkje van med det, og han sagde til Saul: «Eg kann ikkje ganga med dette på meg; eg er ikkje van med det.» Og David lagde det av seg.',
        40: 'So tok han staven sin i handi, og fann seg fem av dei hålaste steinarne i bekkjefaret og lagde deim i gjætarskreppa si, som han hadde på seg. Slyngja si tok han i handi. Og so gjekk han fram imot filistaren.',
        41: 'Filistaren gjekk og fram imot David, og skjoldsveinen hans gjekk fyre.',
        42: 'Då no filistaren gådde David, bles han åt honom; for han var berre ungguten, raudleitt og væn å sjå til.',
        43: 'Filistaren ropa til David: «Meinar du eg er ein hund, sidan du kjem imot meg med stavar?» Og han banna David ved guden sin.',
        44: '«Kom hit til meg!» ropa filistaren til David, «so skal eg gjeva kjøtet ditt åt fuglarne under himmelen og åt villdyri i marki.»',
        45: 'David svara filistaren: «Du kjem imot meg med sverd og langspjot og kastespjot. Men eg kjem imot deg i namnet åt Herren, allhers drott, han som er Gud for Israels-fylkingarne, deim som du hev svivyrdt.',
        46: 'I dag skal Herren gjeva deg i mitt vald. Eg skal fella deg og hogga hovudet ditt av deg. Dei daude skrottarne til filistarheren skal eg i dag gjeva åt fuglarne under himmelen og åt villdyri i marki, so all jordi skal skyna at Israel hev ein Gud,',
        47: 'og heile denne lyden skal skyna at det er ikkje med sverd og spjot Herren gjev siger. Striden høyrer Herren til; han gjev dykk i vår hand.»',
        48: 'Då no filistaren budde seg og gjekk til møtes med David, skunda David seg og sprang fram imot filistaren, burtimot filistarfylkingi.',
        49: 'David stakk handi i skreppa, tok upp ein stein, kasta, og råka filistaren i panna. Steinen sokk i panna hans, so han datt å gruve til jordi.',
        50: 'Soleis vann David på filistaren med ei slyngja si og ein stein, og drap filistaren, endå han hadde ikkje sverd i handi.',
        51: 'David sprang burtåt filistaren, tok sverdet hans, drog det ut or slira og drap honom og hogg hovudet av honom med det. Då filistarane såg at kjempa deira var daud, rømde dei.',
        52: 'Israels-heren og Juda-heren lagde i veg, lyfte herrop, og forfylgde filistarane dit der vegen tek av til Gai, ja heilt til portarne i Ekron; so det låg falne filistarar på vegen til Sa’arajim, ja heilt til Gat og Ekron.',
        53: 'So snudde Israels-heren attende frå forfylgjingi, og herja filistarlægret.',
        54: 'David tok hovudet åt filistaren og førde til Jerusalem; men våpni hans tok han heim til seg.',
        55: 'Då Saul såg David ganga imot filistaren, sagde han med Abner, herhovdingen sin: «Abner, kven er den guten son til?» Abner svara: «So visst som du liver, konge! eg veit ikkje.»',
        56: 'Då sagde kongen: «Få du greide på kven den ungdomen er son til!»',
        57: 'Og då David kom att, etter han hadde felt filistaren, tok Abner og førde honom fram for Saul; han heldt hovudet åt filistaren i handi.',
        58: 'Og Saul spurde honom: «Kven er du son til, guten min?» David svara: «Son til tenaren din, Isai i Betlehem.»',
    },
    18: {
        1: 'Då han hadde tala ut med Saul, lagde Jonatan stor elsk på David, og Jonatan elska honom som seg sjølv.',
        2: 'Saul tok honom til seg den dagen og let honom ikkje venda heim att til far sin.',
        3: 'Jonatan gjorde fostbrorlag med David, av di han elska honom som seg sjølv.',
        4: 'Jonatan tok av seg kappa han bar og gav til David, og våpnkjolen sin, ja jamvel sverdet sitt og bogen sin og beltet sitt gav han honom.',
        5: 'David drog i herferd. Kvar helst Saul sende honom, hadde han lukka med seg. Og Saul sette honom yver krigsheren. Han var vel umtykt av heile folket, endå til av tenarane åt Saul.',
        6: 'Då dei kom heim, etter David hadde felt filistaren, gjekk kvendi ut frå alle byar i Israel, med song og dans, til å møta kong Saul med trummor, fagnadrop og triangel.',
        7: 'Kvendi trødde dansen og song: «Tusund tynte kong Saul, men David tie tusund.»',
        8: 'Då vart Saul brennande harm. Han mislika dei ordi og sagde: «David hev dei gjeve ti tusund; meg hev dei gjeve tusund! No vantar det honom berre kongedømet!»',
        9: 'Og Saul såg jamleg med skakkauga på David frå den dagen.',
        10: 'Dagen etter kom den vonde åndi frå Gud yver Saul. Og han rasa i huset sitt. David spela på harpa, som han kvar dag gjorde. Saul hadde eit spjot i handi.',
        11: 'Saul kasta spjotet og tenkte: «Eg rennar spjotet gjenom David og inn i veggen!» Men David bøygde seg undan, tvo vendor.',
        12: 'Saul vart rædd David, av di Herren var med honom, samstundes som han hadde vike frå Saul.',
        13: 'Saul fekk honom då burt frå seg, med di han sette honom til herførar: han førde herfolket både ut og heim.',
        14: 'David hadde lukka med seg all stad: Herren var med honom.',
        15: 'Då Saul såg at han hadde so stor ei lukka, fekk han rædsla for honom.',
        16: 'Men heile Israel og Juda elska David; for han førde deim både ut og heim.',
        17: 'Saul sagde med David: «Her er eldste dotter mi, Merab; henne gjev eg deg til kona. Berre te deg som ein dugande kar, og før striden for Herren!» Saul tenkte: «Ikkje for mi hand skal han falla, men for filistarane.»',
        18: 'David svara Saul: «Kven er eg? og kva er ætti mi, farsætti mi i Israel, sidan eg skal verta måg til kongen.»',
        19: 'Men då tidi kom at David skulde gifta seg med Merab, dotter åt Saul, gifte han henne med Adriel frå Mehola.',
        20: 'Med Mikal Saulsdotter hadde huglagt David. Saul fekk vita det, og han lika det godt;',
        21: 'for Saul tenkte: «Eg skal gjeva henne åt honom, soleis at ho vert til ei snara for honom, so han fell for filistarhand.» Saul sagde med David: «Andre venda kann du verta mågen min.»',
        22: 'Og Saul baud folki sine: «Kviskra dette ordet i øyra på David: «Kongen likar deg godt, alle folki hans er glad i deg; no må du verta måg til kongen!»»',
        23: 'Då folki åt Saul sagde dette med David, svara han: «Tykkjer de det er so lite å vera kongsmåg? eg er då berre ein ring og fatig kar.»',
        24: 'Tenarane åt Saul fortalde honom det: «So og so sagde David.»',
        25: 'Saul sagde: «Soleis skal de segja med David: «Kongen krev ikkje onnor festargåve enn hundrad huvehold av filistarar; for kongen vil hava hemn yver fiendarne sine.»» Saul vonast fella David med filistarhand.',
        26: 'Tenarane hans melde desse ordi til David; og David lika godt å verta kongsmåg. Fyrr tidi var ute,',
        27: 'reis han upp og gjekk av stad med sveinarne sine og gav tvo hundrad filistarar banehogg. Og David førde huveholdi deira med seg og lagde fullt tal fram for kongen, so han kunde verta kongsmåg. So gav Saul honom Mikal til kona.',
        28: 'Saul såg og skyna at Herren var med David. Mikal Saulsdotter elska honom.',
        29: 'Men Saul vart stendigt meir og meir rædd David. So vart Saul uvenen åt David for heile livet.',
        30: 'Men filistarfyrstarne for i herferd. Og so tidt det for ut, hadde David meir lukka med seg enn hermennerne åt Saul. Og namnet hans vart høgvyrdt.',
    },
    19: {
        1: 'Saul tala med Jonatan, son sin, og med alle tenarane sine um å drepa David. Jonatan Saulsson heldt mykje av David;',
        2: 'difor nemnde Jonatan dette med David og sagde: «Saul, far min, lurar på å drepa deg. Sjå deg fyre i morgon og haldt deg roleg på eit løynd stad, og gøym deg der!',
        3: 'So vil eg ganga ut med far og standa med honom på marki der du er; eg vil nemna deg med far; og vert eg visare med noko, skal du få vita det.»',
        4: 'Jonatan tala Davids sak hjå Saul, far sin, og sagde: «Kongen må ikkje gjera synd på David, tenaren sin. For han hev ikkje gjort synd mot deg. Tvert um; det han hev gjort, hev vore til stor bate for deg.',
        5: 'Han våga livet og felte filistaren, og Herren gav so Israel ein stor siger. Du såg det sjølv og gledde deg. Kvifor skulde du gjera synd på skuldlaust blod og drepa David utan grunn?»',
        6: 'Saul lydde Jonatan, son sin. Og Saul svor: «So sant Herren liver: Han skal ikkje lata livet!»',
        7: 'So ropa Jonatan på David og fortalde honom alt dette, og førde honom til Saul, og han var hjå honom som fyrr.',
        8: 'Då krigen tok til att, for David i herferd og stridde mot filistarane, og gjorde stort mannefall millom deim, og dei rømde for honom.',
        9: 'Då kom ei vond ånd frå Herren yver Saul, der han sat heime med spjot i handi, medan David leika på strengjerne.',
        10: 'Då freista Saul å renna spjotet gjenom David inn i veggen. Men han smatt undan, og spjotet for inn i veggen. Og David rømde og kom seg burt same natti.',
        11: 'So sende Saul folk til heimen hans David; dei skulde vakta på honom og drepa honom um morgonen. Men Mikal, kona hans, fortalde honom det og sagde: «Bergar du ikkje livet i natt, so er du feig i morgon.»',
        12: 'So fira Mikal David ned gjenom vindauga; og han rømde, og berga seg undan.',
        13: 'So tok Mikal husguden og lagde i sengi, sette eit net av geitehår kring hovudet, og breidde åklædet yver.',
        14: 'Då no Saul sende folk til å henta David, sagde ho: «Han er sjuk.»',
        15: 'Saul sende då Saul folki til å finna David sjølv, og sagde: «Ber honom hit upp til meg i sengi, so me kann drepa honom!»',
        16: 'Då folki kom inn, fekk dei sjå det var husguden som låg i sengi, med geitehårsnetet kring hovudet.',
        17: 'Saul spurde Mikal: «Kvi hev du svike meg soleis og late uvenen min koma seg undan?» Mikal svara Saul: «Han sagde til meg: «Hjelp meg burt! elles drep eg deg.»»',
        18: 'Men David hadde rømt og berga seg undan. Han gjekk til Samuel i Rama, og fortalde honom alt det Saul hadde gjort honom. Og han og Samuel for til Nevajot og heldt seg der.',
        19: 'Saul fekk vita at David var i Nevajot ved Rama.',
        20: 'Og Saul sende folk til å henta David. Men då sendemennerne fekk sjå profetlyden i profetisk eldhug og Samuel standa der og vera føraren deira, då kom Gudsåndi yver deim, og dei kom i profetisk eldhug, dei og.',
        21: 'Då Saul fekk høyra det, sende han andre folk dit; dei og kom i profetisk eldhug. Og då han tridje venda sende nye folk, gjekk det like eins med deim.',
        22: 'Då gjekk han sjølv til Rama. Då han kom til den store brunnen i Seku, spurde han: «Kvar er Samuel og David?» Dei svara: «I Nevajot ved Rama.»',
        23: 'Då han gjekk dit, til Nevajot ved Rama, kom gudsåndi yver honom og, so han gjekk i profetisk eldhug heile vegen, til dess han kom til Nevajot ved Rama.',
        24: 'Då reiv han og av seg klædi, med di han og vart teken av profetisk eldhug framfor Samuel. Og han datt i koll og låg der naken heile den dagen og natti med. Difor plar dei segjer: «Er Saul og millom profetarne?»',
    },
    20: {
        1: 'David rømde frå Nevajot ved Rama, og kom til Jonatan og sagde: «Kva hev eg gjort? Kva ugjerning og kva synd hev eg gjort far din, etter di han vil taka livet av meg?»',
        2: 'Han svara honom: «Aldri i verdi skal du døy! Sjå far gjer aldri noko, anten smått eller stort, utan han let meg vita det. Kvifor skulde då far løyna dette for meg? Det er ikkje so!»',
        3: 'Men David gjorde eid på det: «Far din veit alt for vel at du hev fenge godvilje for meg. Difor tenkjer han: «Lat ikkje Jonatan få greida på dette! elles fær han sorg.» Men so sant Herren liver, og so sant du sjølv liver: det er berre eit stig millom meg og dauden.»',
        4: 'Då sagde Jonatan med David: «Kva ynskjer du eg skal gjera for deg?»',
        5: 'David svara: «I morgon er det nymåne. Eg skulde då sitja til bords med kongen. Lat meg no ganga og løyna meg ute på marki til i yvermorgon kveld.',
        6: 'Skulde då far din sakna meg, so seg: «David nidbad meg um løyve til å springa heim til Betlehem, der som heile ætti no ber fram det årlege slagtofferet sitt.»',
        7: 'Segjer han då: «Det er vel!» so kann tenaren din vera trygg. Men kjem sinnet yver honom, so skynar du han er fast meint på eitkvart ilt.',
        8: 'Syn då godvilje mot tenaren din, sidan du hev late tenaren din gjera fostbrorlag med meg for Herren! Finst det nokor ugjerning eg hev gjort, so drep du meg! Kvifor skulde du føra meg til far din?»',
        9: 'Då svara Jonatan: «Aldri i verdi! Skynar eg klårt at far vil deg eitkvart ilt, so skal eg sanneleg segja deg det.»',
        10: 'Då spurde David: «Kven skal no lata meg vita dette, um far din gjev deg eit hardt svar?»',
        11: 'Jonatan svara: «Kom, lat oss ganga ut på marki!» Og dei gjekk båe ut på marki.',
        12: 'Og Jonatan sagde med David: «Vitne er Herren, Israels Gud: når eg i morgon eller i yvermorgon ved denne tid røynar ut huglaget til far, og finn at det læt godt for David, so skal eg sanneleg senda bod til deg og lata deg vita det.',
        13: 'Herren lata Jonatan bøta for det no og sidan: um far kjem på å gjera deg noko ilt, so let eg deg vita deg, og hjelper deg til å koma undan, so du kann fara din veg i fred. Og Herren vere med deg, som han hev vore med far!',
        14: 'Og vil so du, um eg endå liver, vil du so ikkje syna Herrens godvilje mot meg, so eg slepp lata livet?',
        15: 'Aldri i æva vil du vel taka godviljen burt frå ætti mi, jamvel når Herren tek alle uvenerne åt David burt frå jordi.»',
        16: 'So gjorde Jonatan ei pakt med Davids hus og sagde: «Herren take hemn yver uvenerne åt David!»',
        17: 'Og Jonatan tok David i eid endå ein gong ved sin kjærleik til honom; for han elska honom som han elska si eigi sjæl.',
        18: 'Jonatan sagde til honom: «I morgon er det nymåne. Då vert du sakna, av di sessen din kjem til å sakna deg.',
        19: 'I yvermorgon skal du skunda deg ned til løynstaden din, der du løynde deg den dagen det du veit skulde gjerast; og haldt deg attmed Burtferd-steinen.',
        20: 'Eg vil då vera i nærleiken og skjota til måls med tri piler.',
        21: 'So sender eg sveinen min av stad til å leita upp pilerne. Brukar eg då desse ordi til sveinen: «Sjå pilerne ligg på denne sida, tak deim!» - so kann du koma fram; for då er det ingen fåre for deg og ingen ting i vegen, so sant Herren liver.',
        22: 'Men segjer eg til guten: «Sjå pilerne ligg lenger burte!» so far din veg! for då sender Herren deg burt.',
        23: 'Til æveleg tid er Herren vitne til det ordet eg og du hev tala saman.»',
        24: 'So løynde David seg ute på marki. Då nymånedagen kom, sette kongen seg til bords til å eta.',
        25: 'Kongen sat på sin vanlege sess, høgsætet attmed veggen; Jonatan stod upp, og Abner sat ved sida av Saul. Men sessen åt David var tom.',
        26: 'Saul gat ingen ting den dagen; for han tenkte: «Det hev vel hendt honom noko, so han ikkje er rein, av di han endå ikkje hev reinsa seg.»',
        27: 'Men då sessen åt David stod tomt ogso næste dag, dagen etter nymånedagen, spurde Saul Jonatan, son sin: «Kvi hev ikkje Isaisonen kome til bords antan i går eller i dag?»',
        28: 'Jonatan svara Saul: «David nidbad meg um løyve til å fara åt Betlehem;',
        29: 'han sagde: «Lat meg fara, for me held offerfest heile ætti der i byen, og bror min hev sjølv bode meg koma; held du aldri so lite av meg, so lat meg få lov å fara heim so eg kann vitja brørne mine!» Difor kjem han ikkje til kongsbordet.»',
        30: 'Då vart Saul brennande harm på Jonatan og sagde til honom: «Du son til ei treisk og rangsnudd kvinna! Visste eg ikkje at du hev huglagt Isaisonen, til skjemsla for deg sjølv, og til skjemsla for blygsli åt mor di!',
        31: 'So lenge Isaisonen liver, stend både du og kongedømet ditt på utrygg grunn. Send difor bod og henta honom til meg! for han skal vera feig.»',
        32: 'Jonatan svara Saul, far sin: «Kvifor skal han lata livet? Kva hev han gjort?»',
        33: 'Då kasta Saul spjotet imot honom, og vilde drepa honom. No skyna Jonatan at far hans var fast meint på å drepa David.',
        34: 'Jonatan reis upp frå bordet, harm i hugen, og smaka ikkje matbiten denne andre nymånedagen; for han syrgde sårt yver David, av di far hans hadde svivyrdt honom.',
        35: 'Morgonen etter gjekk Jonatan ut på marki den tid han hadde avtala med David; og ein liten svein var med honom.',
        36: 'Han sagde til sveinen: «Spring du og leita etter pilerne som eg skyt!» Medan sveinen sprang av stad, skaut han ut pili framum honom.',
        37: 'Då sveinen nådde dit pili låg som Jonatan hadde skote, ropa Jonatan etter sveinen: «Pili ligg då lenger burte!»',
        38: 'Framleides ropa Jonatan etter sveinen: «Nøyt deg! skunda deg! statt ikkje der!» Då sanka sveinen åt Jonatan pilerne og bar til husbonden sin.',
        39: 'Sveinen skyna ingen ting; einast Jonatan og David skyna meiningi.',
        40: 'Jonatan gav våpni sine til sveinen som var med honom, og sagde: «Far heim til byen med deim!»',
        41: 'Då sveinen var faren, reis David upp på sørsida. Han fall å gruve til jordi, og bøygde seg tri gonger. Dei kysste einannan, og gret med einannan. Og David stridgret.',
        42: 'Jonatan sagde til David: «Far i fred! Lat det standa med magt det me batt med ein eid i Herrens namn, då me sagde: «Herren skal vere vitne millom meg og deg, og millom mi ætt og di ætt, til æveleg tid!»» So reis David upp og gjekk sin veg. Og Jonatan gjekk heim att til byen.',
    },
    21: {
        1: 'David kom til presten Ahimelek i Nob. Ahimelek vart forstøkt då han fekk sjå David, og spurde: «Kvifor kjem du eismall og hev inkje folk med deg?»',
        2: 'David svara presten Ahimelek: «Kongen hev gjeve meg ei ærend, og han sagde med meg: «Ingen må vita noko um ærendi eg sender deg i og legg på deg.» Og sveinarne mine hev eg varsla å møta meg der dei veit.',
        3: 'Gjev meg no det du hev for handi, fem brød, eller kva som finst!»',
        4: 'Presten svara David: «Uvigt brød hev eg ikkje for handi; einast heilagt brød er her; berre sveinarne dine hev halde seg burte frå kvinnor.»',
        5: 'David svara presten: «Ver trygg! kvinnor hev vore langt burte frå oss alt sidan fyrre dagen. Då eg drog av stad, hadde sveinarne mine helgar-likamar. Um ferdi vår er kvardagsleg, so er ho då helga ved likamen i dag.»',
        6: 'So gav presten honom heilagt brød; det fanst ikkje anna brød enn skodebrødi som hadde lege framfor Herren, og som no var burttekne att, då nytt brød var framlagt same dagen det gamle vart burtteke.',
        7: 'Den dagen var det ein av Sauls tenarar der, som heldt seg inne framfor Herren, ein edomit, heitte Doeg, som var Sauls yverhyrding.',
        8: 'David spurde Ahimelek: «Hev du ikkje noko spjot eller sverd her hjå deg? Korkje sverdet mitt eller dei hine våpni tok eg med meg, då kongsærendi kom so brått på.»',
        9: 'Presten svara: «Jau, det sverdet som filistaren Goliat åtte, han som du felte i Eikedalen; det ligg sveipt i ei kappa attum messehakelen. Vil du hava det, so tak det! Noko anna hev eg ikkje.» «Det finst ikkje maken til det,» sagde David; «gjev meg det!»',
        10: 'David drog av og rømde same dagen for Saul, og kom til Akis, kongen i Gat.',
        11: 'Tenarane åt Akis sagde: «Er ikkje dette David, kongen i landet? Er det ikkje til æra for honom dei syng so når dei dansar: Tusund tynte Saul, David tie tusund?»',
        12: 'David lagde desse ordi på minne, og vart mykje rædd for Akis, kongen i Gat.',
        13: 'Difor lest han som han var galen, og tedde seg som ein dåre, då dei vilde taka fat på honom; han rita på dørarne i porten, og let siklet renna i skjegget.',
        14: 'Då sagde Akis med tenarane sine: «De ser då mannen hev mist vitet! Kvi fører de honom til meg?',
        15: 'Vantar det meg på vitløysor, sidan de førar denne mannen hit, so han skal te seg galen framfor meg? Kva hev han å gjera her i huset?»',
    },
    22: {
        1: 'David drog derifrå, og kom seg undan til Adullam-hola. Då brørne hans og heile farsætti hans høyrde gjete det, kom dei dit ned til honom.',
        2: 'Og til honom flokka seg allslags folk, alle som var i naud, alle som var i skuld, alle som var misnøgde, og han vart hovdingen deira; ei fire hundrad mann slo lag med honom.',
        3: 'Derifrå drog David til Mispe i Moab. Og han sagde til Moabs-kongen: «Lat far min og mor mi få koma hit og vera hjå dykk, til dess eg fær vita kva Gud vil gjera med meg!»',
        4: 'Han førde deim fram for Moabs-kongen, og dei fekk halda seg hjå honom, so lenge David var i borgi.',
        5: 'Men profeten Gad sagde til David: «Du skal ikkje halda deg her i borgi! tak ut herifrå, og far til Judalandet!» Og David drog burt derifrå og kom til Heretskogen.',
        6: 'Saul frette at dei hadde fenge greide på David og dei folki som var med honom. Saul sat ein dag i Gibea under tamariska på haugen, med spjot i handi; og alle tenarane hans stod ikring honom.',
        7: 'Då sagde Saul med tenarane sine, der dei stod ikring honom: «Høyr no, Benjamins born! Meiner de Isaisonen gjev åkrar og vinhagar åt dykk alle, og set dykk alle til herførar for større eller mindre flokkar?',
        8: 'For de hev alle samansvore dykk mot meg; og ingen hev fortalt meg at son min hev gjort fostbrorlag med Isaisonen! Ingen hev so mykje medkjensle med meg at han hev fortalt meg det. For son min hev eggja tenaren min til meinråder mot meg, so som det no kjem for dagen.»',
        9: 'Edomiten Doeg, som ogso stod der millom folki åt Saul, tok til ords og sagde: «Eg såg Isaisonen kom til Ahimelek Ahitubsson i Nob.',
        10: 'Han spurde Herren for honom, og gav honom nista; og let honom få sverdet åt filistaren Goliat.»',
        11: 'Kongen sende då bod etter presten Ahimelek Ahitubsson og heile ætti hans, prestarne i Nob. Dei møtte alle fram for kongen.',
        12: 'Saul sagde: «Høyr meg, du Ahitubsson!» Han svara: «Kva vil du meg, herre!»',
        13: 'Saul sagde til honom: «Kvifor hev de samansvore dykk mot meg, du og Isaisonen, med di du gav honom mat og sverd, og spurde Gud for honom, og han fekk leggja meinråder mot meg, so som det no kjem for dagen?»',
        14: 'Ahimelek svara: «Kven av alle tenarane sine er so trugen som David? og han er kongsmåg og hovding yver livvakti di og høgvyrd i huset ditt!',
        15: 'Er det fyrste gongen eg hev spurd Gud for honom? Aldri i verdi må kongen saka meg og ætti mi for dette. Eg hev ikkje visst det minste um alt dette.»',
        16: 'Kongen sagde: «Du skal lata livet, Ahimelek! du og heile ætti di.»',
        17: 'Og kongen baud tenarane som stod ikring honom: «Fram og drep Herrens prestar! for dei er og i samråd med David. Endå dei visste han rømde, let dei meg ikkje vita det.» Men kongstenarane torde ikkje rette ut handi og hogga ned Herrens prestar.',
        18: 'Kongen baud då Doeg: «Fram du, og hogg ned prestarne!» Og edomiten Doeg gjekk fram og hogg ned prestarne med eigi hand, og drap den dagen fem og åtteti mann som bar messehakel av lin.',
        19: 'Og folket i prestebyen Nob slo han med sverd, karar og kvende, småborn og store born, bufe og smale og asen, alt hogg han ned med sverdet.',
        20: 'Berre ein av sønerne hans Ahimelek Ahitubsson berga seg undan. Abjatar heitte han. Han rømde til David.',
        21: 'Abjatar fortalde David at Saul hadde hogge ned Herrens prestar.',
        22: '«Eg skyna det alt den gong,» sagde David til Abjatar, «at når edomiten Doeg var der, vilde han melda det til Saul. Eg er upphavet til dråpet på heile di ætt.',
        23: 'Haldt deg hjå meg! ver hugheil! Den som vil taka livet av meg, vil taka livet av deg. Du er no i mi varetekt.»',
    },
    23: {
        1: 'Folk melde til David: «Filistarane held på og strider mot Ke’ila, og dei herjar treskjestaderne.»',
        2: 'Då spurde David Herren: «Skal eg draga av stad og slå desse filistarar?» Herren svara David: «Ja, drag av stad, slå filistarane og fria ut Ke’ila!»',
        3: 'Men folki åt David sagde med honom: «Me er alt fyrr rædde um oss her i Juda. Kor skal det då ganga når me fer til Ke’ila mot filistarfylkingi?»',
        4: 'Då spurde David Herren andre gongen, og Herren svara honom: «Ris upp! drag ned til Ke’ila! Eg gjev filistarane i di hand.»',
        5: 'So for David med kararne sine til Ke’ila og stridde mot filistarane, førde burt buskapen deira, og gjorde stort mannefald millom deim. Soleis fria David folket i Ke’ila.',
        6: 'Då Abjatar Ahimeleksson rømde til David i Ke’ila, hadde han med seg messehakelen.',
        7: 'Saul fekk vita at David var komen til Ke’ila. Då sagde Saul: «Gud hev gjeve honom i mi magt, sidan han hev stengt seg inne i ein by med portar og slåer.»',
        8: 'So baud Saul ut alt folket til strid. Dei skulde draga ned til Ke’ila og kringsetja David og folket hans.',
        9: 'Då no David fekk vita at Saul lagde meinråder mot honom, sagde han til presten Abjatar: «Ber hit messehakelen!»',
        10: 'Og David sagde: «Herre, Israels Gud! Tenaren din hev spurt for sant at Saul tenkjer å koma til Ke’ila og øyda byen for mi skuld.',
        11: 'Vil då Ke’ila-buarne gjeva meg i hans hand? Kjem Saul hit, som tenaren din hev spurt? Herre, Israels Gud! Lat tenaren din få vissa for det!» Herren svara: «Ja, han kjem hit.»',
        12: 'David spurde endå ein gong: «Vil Ke’ila-buarne gjeva meg og kararne mine i Sauls hender?» Herren svara: «Ja, dei vil det.»',
        13: 'Då reis David upp med kararne sine, um lag seks hundrad mann, og drog ut frå Ke’ila, og ferdast kvar helst det høvde. Då Saul fekk melding at David var rømd frå Ke’ila, let han vera å draga ut.',
        14: 'So heldt David seg i øydemarki i fjellborgerne, og heldt seg millom fjelli i øydemarki Zif. Saul leita etter honom allstødt. Men Gud gav honom ikkje hans hand.',
        15: 'Medan David var i Hores i øydemarki Zif, såg han at Saul hadde fare ut og vilde drepa honom.',
        16: 'Jonatan Saulsson for av stad og gjekk til David i Hores, og styrkte modet hans i Gud.',
        17: 'Han sagde til honom: «Ver hugheil! handi hans Saul, far min, skal ikkje nå deg. Du skal verta konge yver Israel, og eg skal vera den andre etter deg. Det skyner ogso Saul, far min.»',
        18: 'So gjorde dei båe ei pakt for Herren. Og David heldt seg i Hores. Men Jonatan for heim att.',
        19: 'Nokre Zif-folk drog upp til Saul i Gibea og sagde: «David held seg løynd hjå oss, i fjellborgerne i Hores, på Hakilahøgdi, sunnanfor øydemarki.',
        20: 'Tekkjest det deg å draga ned no, konge, so gjer det! Vår sak vert det då å gjeva honom i kongens hand.»',
        21: 'Då sagde Saul: «Velsigna av Herren vere de, at de tykkjer synd i meg.',
        22: 'Far no heim, og få endå meir vissa! finn ut og sjå etter kva stad han ferdast, og kven det er som ser honom der! For dei hev sagt meg at han er ein ful fant.',
        23: 'Finn ut og få greida på alle løynstader, der han kann løyna seg! Kom so att til meg, når det hev fenge vissa! so vil eg draga med dykk. Finst han i landet, skal eg vita å leita honom upp, um eg so skal leita millom alle Juda-ætterne.»',
        24: 'So tok dei ut og gjekk til Zif fyre Saul. David og kararne hans var i øydemarki Maon, på heidi sunnanfor øydemarki.',
        25: 'Då no Saul drog av stad med folki sine på leit etter David, fekk David høyra gjete det, og drog då ned på ein hamar, og heldt seg i øydemarki Maon. Då Saul frette det, sette han etter David inn i øydemarki Maon.',
        26: 'Saul gjekk på den eine fjellsida, og David og kararne hans på hi. Nett som no David gjekk i angest og vilde sleppa frå Saul, og Saul og folki hans freista ringa David og kararne hans og fanga deim,',
        27: 'so kom det bod til Saul: «Skunda deg og kom! filistarane hev falle inn i landet.»',
        28: 'So heldt Saul upp med å forfølja David, og drog mot filistarane. Derav fekk den staden namnet Sela-Hammahlekot.',
    },
    24: {
        1: 'David drog upp derifrå, og heldt seg so i fjellborgerne i En-Gedi.',
        2: 'Då Saul kom heim att frå herferdi mot filistarane, fekk han tiend at David var i øydemarki En-Gedi.',
        3: 'Då tok Saul tri tusund mann, utvalde or heile Israel, og drog av stad på leit etter David og kararne hans austum Steinbukk-hamrarne.',
        4: 'Han kom til sauegardarne attmed vegen; der var det ein heller; og der inn gjekk Saul for seg sjølv. David og kararne hans sat inst i helleren.',
        5: 'Då sagde folki åt David med honom: «No er dagen komen som Herren nemde med deg: «Eg vil gjeva uvenen din i handi di, so du kann gjera med honom etter eige tykkje.»» David reis upp og skar i løyndom ein snipp av kappa åt Saul.',
        6: 'Men so fekk David samvitsagg, av di han hadde skore av kappesnippen for Saul.',
        7: 'Og han sagde med kararne sine: «Aldri i verdi vil Herren at eg skal gjera sovore og leggja hand på herren min som Herren hev salva; for han er den som Herren hev salva.»',
        8: 'David truga kararne sine med strenge ord og gav deim ikkje lov til å falla yver Saul. Men då Saul reis upp og gjekk ut or helleren og skulde fara lenger,',
        9: 'då reis David og upp, gjekk ut or helleren og ropa etter Saul: «Herre konge!» Då Saul såg seg attende, kasta David seg å gruve på jordi. Han bøygde seg,',
        10: 'og ropa til Saul: «Kvi høyrer du på det folk segjer, at David lurar på eitkvart ilt mot deg?',
        11: 'Med eigne augo hev du set i dag kor eg sparde deg, endå Herren hadde gjeve deg i mi hand i helleren, og dei rådde meg til å drepa deg. Men eg sparde deg, med di eg tenkte: «Ikkje vil eg leggja hand på herren min; for han er den Herren salva.»',
        12: 'Sjå sjølv, far! ja sjå her snippen av kappa di i mi hand! Når eg skar av kappesnippen og ikkje drap deg, so må du då skyna og sjå at eg ikkje etlar deg noko ilt eller noko brot, og at eg ikkje hev gjort synd mot deg, endå du sit etter meg og vil taka livet av meg.',
        13: 'Herren skal døma oss imillom, og Herren skal hemna meg på deg. Men mi hand skal ikkje vera lyft mot deg.',
        14: 'Det er som det gamle ordtøket segjer: «Frå dei vonde kjem vondskap.» Men mi hand skal ikkje vera lyft mot deg.',
        15: 'Kven er det Israels konge hev drege ut imot? Kven er det du forfylgjer? Ein daud hund! ei einsleg loppa!',
        16: 'Herren skal vera domar og døma oss imillom. Han skal sjå til og føra mi sak, ja døma meg fri frå deg.»',
        17: 'Då David hadde tala ut med Saul, ropa Saul til David: «Er det di røyst dette, David, son min?» Og Saul sette i og gret.',
        18: 'Og han sagde til David: «Retten er på di sida og ikkje på mi. Du hev gjort godt mot meg, medan eg hev gjort ilt mot deg.',
        19: 'I dag hev du synt kor god du er mot meg, med di du ikkje drap meg, endå Herren hadde gjeve meg i di hand.',
        20: 'Når ein råkar uvenen sin, plar ein då lata honom fara i fred? Herren gjeva deg lika for det gode du synte meg i dag!',
        21: 'Sjå no skynar eg at du skal verta konge, og at kongedømet yver Israel skal vera fast i di hand.',
        22: 'Men gjer no eid ved Herren at du ikkje vil rydja ut mi ætt etter meg og ikkje strjuka ut namnet mitt or ætti mi!» David gjorde den eiden til Saul. So for Saul heim. David og kararne hans drog upp i fjellborgi.',
    },
    25: {
        1: 'Samuel døydde. Heile Israel kom i hop og gret yver honom. Dei gravlagde honom heime i Rama. David braut upp og drog ned til øydemarki Paran.',
        2: 'I Maon var det ein mann som hadde buskapen sin på Karmel. Den mannen var ovleg rik; han åtte tri tusund sauer og tusund geiter. Han heldt på nett då å klyppa sauerne sine på Karmel.',
        3: 'Nabal heitte mannen, og kona hans heitte Abiga’il. Kona hans var både vitug og væn; men mannen var hardlyndt og vondlyndt. Han var av Kalebs-ætti.',
        4: 'Då no David høyrde gjete i øydemarki at Nabal heldt på å klyppa sauerne,',
        5: 'sende han ti av sveinar med den ordsendingi: «Far upp til Karmel! Gakk til Nabal og helsa honom frå meg:',
        6: '«Heil og sæl!» skal det segja, «og fred med deg sjølv! fred med ditt hus! og fred med alt det du eig!',
        7: 'Eg hev spurt at du held på med saueklypping. No er det so at hyrdingarne dine hev halde seg i vårt grannelag, og me hev ikkje gjenge deim for nær, og dei hev ikkje sakna noko slag heile den tidi dei hev vore på Karmel.',
        8: 'Spør tenarane dine, so vil dei sjølve segja deg det. Syn no godvilje mot sveinarne mine! Du veit me hev kome hit i ei god stund. Gjev tenarane dine og David, son din, det du hev for handi!»»',
        9: 'Då sveinarne åt David kom dit, tala dei til Nabal i Davids namn og sagde som han hadde bode deim; og so tagde deim og gav tol.',
        10: 'Nabal svara tenarane åt David: «Kven er David? Kven er Isaisonen? No um dagen stryk det so mange tenarar frå husbondsfolki sine.',
        11: 'Skulde eg taka min mat og min drykk og slagt, som eg hev etla åt saueklypparane mine, og gjeva åt folk som eg ikkje veit kvar dei høyrer heime?»',
        12: 'Sveinarne åt David vende då um og gjekk sin veg. Då dei kom attende, melde dei honom alt dette.',
        13: 'Då baud David: «Alle mann spenner sverdet um seg!» Og alle so gjorde. David sjølv spente og sverdet um seg. Um lag fire hundrad mann fylgde David upp; dei hine tvo hundrad mann heldt seg attmed tyet.',
        14: 'Men ein av drengjerne hadde meldt det til Abiga’il, kona hans Nabal: «David sende bod hit frå øydemarki og helsa husbond; men han hylja deim yver.',
        15: 'Men desse kararne hev gjort oss mykje gagn. Ikkje hev dei gjenge oss for nær, og aldri hev me sakna noko heile den tidi me ferdast i lag med deim der ute på marki.',
        16: 'Dei var ein mur ikring oss natt og dag, heile tidi me heldt oss i deira grannelag og gjætte småfeet.',
        17: 'Tenk difor yver, og finn på eitkvart! for det heng ei ulukka yver husbond og heile huset hans; han er slik ei uvyrda, at ingen vågar tala til honom.»',
        18: 'Då skunda Abiga’il seg og tok tvo hundrad brød, tvo vinhitar, fem tillaga sauer, ti settungar steikte aks, hundrad rosinkakor og tvo hundrad fikekakor, og klyvja på asni.',
        19: 'Og ho sagde til drengjerne: «Far i fyrevegen! Sjå eg kjem etter.» Men med Nabal, mannen sin, gat ho det ikkje.',
        20: 'Då ho reid på asnet sitt og kom ned i livd av fjellet, fekk ho sjå David og kararne hans koma ned frå hi sida, so ho måtte møta deim.',
        21: 'David hadde sagt: «Til fåfengs hev eg verna um alt det den mannen åtte i øydemarki, so ingen ting vanta av all eigedomen hans. Og han gjev meg vondt i vederlag for godt.',
        22: 'So sant Gud må lata uvenerne åt David bøta no og sidan - av alle deim som høyrer honom til, let ikkje eit einaste karmannsemne liva til dagsprett i morgon.»',
        23: 'Då no Abiga’il fekk sjå David, steig ho straks ned frå asnet, fall å gruve for David og bøygde seg mot jordi.',
        24: 'Ho fall ned for føterne hans og sagde: «Mi er skuldi, herre! Men lat terna di få tala med deg! og høyr på ordi åt terna di!',
        25: 'Ikkje må du bry deg um Nabal, den uvyrda. Det namnet hans tyder, det er han; dåre heiter han, og dårskap hyser han. Men eg, terna di, eg hev ikkje set dei sveinarne du sende, herre!',
        26: 'Og no, herre! so sant som Herren liver, og so sant du sjølv liver, og Herren hev meinka deg frå blodskuld og sjølvtekt - gjev det må ganga med uvenerne dine og alle som lurer på å gjera deg mein, like eins som det gjeng med Nabal!',
        27: 'Lat no desse gåvor, som terna di hev ført med til deg, verta utskifte millom dei sveinarne som fylgjer deg!',
        28: 'Herre, tilgjev terna di det ho hev synda! Herren skal visseleg byggja upp åt deg, herre, eit hus som vert standande. For du herre, fører striden for Herren. Inkje vondt hev dei funne hjå deg heile ditt liv.',
        29: 'Ris det upp nokon og forfylgjer deg og vil taka livet av deg, gjev so ditt liv, herre, må vera bunde i bundelen av dei livande hjå Herren, din Gud! Men livet åt uvenerne dine skal han leggja i slyngja, og slengja burt.',
        30: 'Når Herren gjer med deg, herre, alt det gode han hev lova deg, og set deg til fyrste yver Israel,',
        31: 'so skal ikkje dette verta til støytestein eller til samvitsagg for deg, herre, at du hev rent ut skuldlaust blod, og at du, herre, hev teke deg sjølv til rettes. Men når Herren gjer godt med deg, herre, so kom i hug terna di!»',
        32: 'Då svara David Abiga’il: «Lova vere Herren, Israels Gud, som i dag hev sendt deg til møtes med meg!',
        33: 'Velsigna vere vitet ditt! og velsigna vere du sjølv, som i dag meinkar meg i blodskuld og sjølvtekt.',
        34: 'Men so sant Herren, Israels Gud, liver, han som hev halde meg frå å gjera deg noko mein - hadde du ikkje straks møtt meg, so vilde ikkje karmannsemne vore att i huset hans Nabal ved solarkoma i morgon.»',
        35: 'David tok då imot av henne det ho førde med seg til honom. Og han sagde med henne: «Far heim att i fred! Sjå, eg hev lydt dine ord og gjort som du bad.»',
        36: 'Då no Abiga’il kom heim til Nabal, heldt han nett gilde heime. Det var som eit kongsgilde. Og Nabal var lystig og fjåg, og han var ovdrukken. Difor gat ho ikkje det minste med honom, fyrr um morgonen ved dagsprett.',
        37: 'Men morgonen etter, då Nabal hadde sove ut ruset, fortalde kona hans det som var hendt. Då lamdest hjarta hans i bringa, og han vart som ein stein.',
        38: 'Kring ti dagar etter slo Herren Nabal, og han døydde.',
        39: 'Då David spurde at Nabal var dåen, sagde han: «Lova vere Herren som hev hemnt på Nabal den svivyrding han synte meg, og som meinka tenaren sin frå å gjera vondt, med di Herren let vondskapen hjå Nabal koma att på hans eige hovud!» David sende bod og bela til Abiga’il og vilde hava henne til kona.',
        40: 'Då tenarane åt David kom til Abiga’il på Karmel, bar dei fram målemnet sitt: «David hev sendt oss for å bela til deg for honom.»',
        41: 'Då reis ho upp og å fall å gruve til jordi og sagde: «Sjå, terna di er viljug til å vera ei trælkvinna som tvær føterne åt tenarane til herren min.»',
        42: 'So skunda Abiga’il seg, reis upp og sette seg på asnet; like eins dei fem ternorne hennar som var fylgjet hennar. So fylgde ho med sendemennerne til David. Og ho vart kona hans.',
        43: 'David hadde dessutan teke til kona Ahinoam frå Jizre’el, so båe desse tvo vart konorne hans.',
        44: 'Men Saul hadde gjeve Mikal, dotter si, kona hans David, åt Palti La’isson frå Gallim.',
    },
    26: {
        1: 'Folk frå Zif kom til Saul i Gibea og sagde: «Meiner du ikkje David held seg løynd på Hakilahøgdi, beint imot øydemarki!»',
        2: 'Saul tok på veg ned til øydemarki Zif med tri tusund mann, utvalde or Israel, på leit etter David i Zifmarki.',
        3: 'Saul lægra seg på Hakilahøgdi beint imot øydemarki, attmed vegen. David heldt seg då i øydemarki. Då han skyna at Saul var komen etter honom inn i øydemarki,',
        4: 'sende han ut njosnarar, og fekk vita for visst at Saul var komen.',
        5: 'So braut David upp og drog til den staden der Saul hadde lægra seg. David såg staden der Saul låg saman med herhovdingen, Abner Nersson. Saul låg i vognborgi, og folket hans var lægra rundt ikring honom.',
        6: 'David tok til ords og spurde hetiten Ahimelek og Abisai Serujason, bror åt Joab: «Kven vil ganga med meg ned til Saul i lægret?» Abisai svara: «Eg gjeng med deg.»',
        7: 'So kom David og Abisai nattars tid til herfolket der, og såg Saul låg og sov i vognborgi; med spjotet stunge i marki attmed hovudgjerdi. Abner og herfolket låg rundt ikring honom.',
        8: 'Då sagde Abisai til David: «I dag hev Gud gjeve uvenen din i di hand! Lat meg no få renna spjotet gjenom honom ned i marki! Det gjer eg med ein einaste støyt, eg tarv ikkje gjeva honom fleire.»',
        9: 'Men David svara: «Du fær ikkje gjeva honom mein! Kven hev strafflaust lagt hand på den Herren salva?»',
        10: '«So sant Herren liver,» sagde David, «Herren lyt sjølv slå honom, eller avferdsdagen hans må koma på vanleg vis, eller han lyt få sin bane i krigen.',
        11: 'Aldri i verdi vil Herren at eg skal leggja hand på den Herren hev salva. Tak likevel spjotet attmed hovudgjerdi, og vatskrukka! Lat oss so ganga vår veg!»',
        12: 'David tok då spjotet og vatskrukka frå hovudgjerdi åt Saul, og so gjekk dei sin veg. Det var ingen som gådde og ingen som hådde, og ingen som vakna: Dei sov alle i hop. Herren hadde late ein tung svevn falla yver deim.',
        13: 'Då David var komen på hi sida, steig han fram på ein fjellknaus langt burte, so det var langt imillom deim.',
        14: 'Og David ropa til herfolket og til Abner Nersson: «Vil du ikkje svara, Abner?» Abner svara: «Kven er du som ropar til kongen?»',
        15: 'David ropa til Abner: «Du er då ein makelaus kar! I heile Israel finst ikkje maken! Korleis vaktar du kongen, din herre? Det hev vore einkvan inne og vilja gjera mein på kongen, herren din.',
        16: 'Det er ikkje vel gjort, det som du hev gjort. So sant Herren liver, de hadde fortent å lata livet, av di de ikkje hev vakt yver herren dykkar, honom som Herren salva. Sjå no etter: kvar er kongens spjot, og vatskrukka som stod attmed hovudgjerdi hans?»',
        17: 'Saul kjende att røysti hans David og sagde: «Det er då di røyst dette, David, son min!» David svara: «Ja, herre konge!»',
        18: 'Og han sagde: «Kvifor forfylgjer du, herre, tenaren din soleis? Kva hev eg då gjort? Kva vondt finst hjå meg?',
        19: 'Gjev du, herre konge, no vil høyra på tenaren din: Er det Herren som hev eggja deg imot meg, so lat honom få kjenna lukti av ei offergåva! Men er det manneborn som hev eggja deg, so vere dei bannstøytte av Herren, av di dei hev jaga meg burt, so eg no ikkje slå lag med Herrens eigen lyd! Det er som dei vil segja: «Far av og ten framande gudar!»',
        20: 'Og må ikkje no blodet mitt renna ut på marki langt frå Herrens åsyn, når Israels-kongen dreg ut på leit etter ei einsleg loppa, liksom ein veidar rapphøns på heiderne?»',
        21: 'Då sagde Saul: «Eg hev synda. Kom heim att, David, son min! Eg vil ikkje gjera deg noko ilt, etter du i dag hev halde livet mitt so dyrt. Sjå, eg hev fare uvisleg, eg hev bore meg reint gale åt.»',
        22: 'David svara og sagde: «Sjå her er spjotet, konge! Lat ein av sveinarne dine koma hit og henta det!',
        23: 'Og Herren skal løna kvar ein som er ærleg og trufast, soleis som eg var i dag; då Herren gav deg i mi hand og eg vilde ikkje leggja hand på den som Herren hev salva.',
        24: 'Difor: liksom eg hev halde ditt liv so høgt i dag, so skal Herren og halda mitt liv høgt, og han skal fria meg ut or all naud.»',
        25: 'Saul sagde med David: «Velsigna vere du, David, son min! Det du tek deg fyre, skal du ogso sanneleg magtast gjera.» So for David sin veg, og Saul drog heim att.',
    },
    27: {
        1: 'Men David sagde med seg sjølv: «Ein dag stupar eg for Sauls hand. Eg veit ingen annan utveg enn å røma til Filistarlandet; då lyt Saul slutta å leita etter meg innanfor Israelslandskilet; og so bergar eg meg undan honom.»',
        2: 'So braut David upp og drog med dei seks hundrad kararne sine yver til Akis Maoksson, kongen i Gat.',
        3: 'Og David heldt seg hjå Akis i Gat, han og kararne hans, alle med huslyden sin, David med dei tvo konorne sine; Ahinoam frå Jizre’el og Abiga’il, kona hans Nabal frå Karmel.',
        4: 'Då Saul frette at David hadde rømt til Gat, leita han ikkje meir etter honom.',
        5: 'David sagde til Akis: «Hev du aldri so liten godvilje for meg, so lat meg få bu i ein av landsbyarne, so eg kann halda meg der. Kvifor skulde tenaren din bu i hovudstaden hjå deg?»',
        6: 'Akis gav honom Siklag same dagen. Difor høyrer Siklag den dag i dag til Juda-kongarne.',
        7: 'Den tid David budde i Filistarlandet, var i alt eitt år og fire månader.',
        8: 'David tok ut med kararne sine og gjorde herjeferder hjå gesuritarne, girzitarne og amalekitarne. For desse folkeætterne budde der i landet frå gamalt, burtimot Sur og heilt til Egyptarland.',
        9: 'Og når David herja i landet, sparde han korkje kar eller kvende; han tok bufe og smale og asen og kamelar og klæde. Og dermed snudde han attende til Akis.',
        10: 'Når då Akis spurde: «I dag hev de vel ikkje gjort nokor herjeferd?» so svara David: «Jau, sør i Judalandet,» eller: «Sør i Jerahme’eitlandet», eller: «Sør i Kenitarlandet.»',
        11: 'Ingi livande sjæl sparde David, so dei kunde koma til Gat. For han tenkte: «Dei kunde slarva um oss og segja: «Det og det hev David gjort; soleis hev han fare åt heile tidi han budde i Filistarlandet.»»',
        12: 'Men Akis trudde David, og tenkte: «Han hev fenge uord på seg hjå Israel, folket sitt, og no vil han tena meg alle dager.»',
    },
    28: {
        1: 'I dei dagarne fylkte filistarane krigsherane sine til strid mot Israel. Og Akis sagde med David: «Det skal du vita for visst, at du og kararne dine lyt fara i herferd med meg!»',
        2: 'David svara Akis: «Ja vel, då skal du ogso røyna kva tenaren din duger til!» Akis sagde med David: «Ja vel, so set eg deg til livvakt hjå meg alle dagar.»',
        3: 'Samuel var dåen. Heile Israel hadde gråte yver honom. Og dei hadde gravlagt honom heime i Rama. Og Saul hadde rudt ut or landet deim som mana fram draugar og spåvette.',
        4: 'Filistarane fylgte seg og lagde seg i læger attmed Sunem. Då fylkte ogso Saul heile Israel, og dei lægra seg ved Gilboa.',
        5: 'Då Saul såg filistarlægret, vart han so rædd at hjarta hans skalv.',
        6: 'Og Saul spurde Herren. Men Herren svara honom ikkje, antan gjenom draumar eller gjenom urim eller gjenom profetar.',
        7: 'Då sagde Saul med tenarane sine: «Leita upp for meg ei som manar fram draugar, so gjeng eg åt henne og gjer spursmål til henne.» Tenarane svara: «I En-Dor er ei kona som manar fram draugar.»',
        8: 'Saul gjorde seg ukjenneleg, tok på seg andre klæde, og gjekk avstad med tvo fylgjesveinar. Dei kom til kona nattars tid. Og han sagde: «Få ein draug til å spå meg! Mana fram åt meg den eg nemner for deg!»',
        9: 'Kona svara: «Du veit då sjølv kva Saul hev gjort, at han hev rudt ut or landet deim som manar fram draugar og spåvette. Kvifor vil du då leggja ut snaror for meg, so eg må lata livet?»',
        10: 'Saul svor ein eid til henne ved Herren og sagde: «So sant Herren liver: ingi skuld skal råka deg for denne saki!»',
        11: 'Kona spurde: «Kven vil du eg skal mana for deg?» Han svara: «Mana fram åt meg Samuel!»',
        12: 'Då kona fekk sjå Samuel, sette ho i eit høgt skrik. Og ho sagde med Saul: «Kvifor hev du svike meg? Du er Saul!»',
        13: 'Kongen svara: «Ver hugheil! Kva er det du ser?» Kona sagde: «Eg ser ein gud koma upp or jordi.»',
        14: '«Korleis ser han ut?» spurde han. Ho svara: «Det er ein gamall mann som kjem upp, sveipt i ei kåpa.» Då skyna Saul det var Samuel, og lutte andlitet mot jordi og bøygde seg for honom.',
        15: 'Og Samuel spurde Saul: «Kvi uroar du meg og manar meg fram?» Saul svara: «Eg er i stor naud. Filistarane fører krig mot meg, og Gud hev vike frå meg og svarar meg ikkje, anten gjenom profetar eller gjenom draumar. Difor kalla eg på deg, so eg fær vita kva eg skal gjera.»',
        16: 'Samuel svara: «Kvi spør du meg, når Herren hev vike frå deg og hev vorte uvenen din?',
        17: 'Herren hev no gjort med deg som han sagde gjenom min munn: Herren hev rive riket ut or di hand og gjeve det åt ein annan, åt David.',
        18: 'Av di du ikkje lydde Herren og ikkje let den brennande harmen hans råka Amalek, difor hev Herren gjort dette mot deg no.',
        19: 'Herren vil gjeva både deg og Israel i filistarmagt. I morgon skal du og sønerne dine vera hjå meg. Og jamvel Israels-lægret vil Herren gjeva i filistarmagt.»',
        20: 'Då datt Saul brått til jordi so lang han var; so forfærd vart han for ordi frå Samuel. Magtløysa tok honom; for han hadde ikkje smaka matbiten eit heilt døger.',
        21: 'Kona gjekk fram åt Saul. Og då ho såg kor reint forstøkt han var, sagde ho med honom: «Sjå terna di lydde deg, og eg våga livet og rette meg etter dei ordi du tala åt meg.',
        22: 'So lyd no du terna di, so vil eg setja fram litevetta mat åt deg, og du må eta, so du kann magtast att fyrr du fer din veg.»',
        23: 'Han vilde ikkje: «Eg vil ikkje eta», sagde han. Men då både tenarane og kona naubad honom, so let han seg segja, reis upp, og sette seg på sengi.',
        24: 'Kona hadde ein gjødkalv heime. Ho skunda seg, fekk slagta honom. So tok ho mjøl, knoda og baka søtebrød.',
        25: 'So bar ho det fram for Saul og tenarane. Og då dei hadde ete, reis dei upp, og gjekk av stad same natti.',
    },
    29: {
        1: 'Filistarane fylkte alle herarne sine i Afek. Israel låg i læger attmed kjelda i Jizre’el.',
        2: 'Filistarfyrstarne gjekk fram med sine hundrad mann og sine tusund. Og David og kararne hans kom attarst, i lag med Akis.',
        3: 'Filistarfyrstarne spurde: «Kva hev desse hebræarane her å gjera?» Akis svara: «De veit då at David som var hirdmann hjå Saul, Israels-kongen, han hev vore hjå meg år og dag, og eg hev aldri funne nokon ting å segja på honom frå den stund han vart min mann og til i dag.»',
        4: 'Men filistarfyrstarne vart forarga på honom, og dei sagde ifrå til honom: «Send den karen heim att! Lat honom halda seg på den staden du hev sett honom yver! Lat honom ikkje fara i strid saman med oss! Midt i slaget kann han venda seg mot oss. Kor kunde han betre vinna att godviljen hjå herren sin, enn med hovudi av hermennerne våre?',
        5: 'Er det ikkje til æra for denne David at dei syng med dei dansar: «Tusund tynte Saul men David tie tusund»?»',
        6: 'Då kalla Akis David til seg og sagde: «So sant Herren liver: Du er ein ærleg kar! og eg likar godt å sjå deg ganga ut og inn hjå meg i lægret. For eg hev inkje vondt funne hjå deg frå den stund du kom til meg og heilt til no. Men fyrstarne likar deg ikkje.',
        7: 'So far heim att i fred, so du ikkje skal gjera noko som filistarfyrstarne mislikar.»',
        8: 'David sagde med Akis: «Kva hev eg då gjort? og kva hev du funne å segja på tenaren din frå den dagen eg kom fram for deg og heilt til i dag, etter som du negtar meg å ganga i strid mot uvenerne dine, herre konge?»',
        9: 'Akis svara: «Eg veit best sjølv at eg held deg som ein gudsengel! Men filistarfyrstarne stend på sitt: han fær ikkje vera med oss i striden.',
        10: 'Ris no tidleg upp i morgon, du og tenarane åt herren din som er komne med deg; og når det de hev gjort, so far dykkar veg so snart det ljosnar!»',
        11: 'David og kararne hans reis då upp tidleg, for sin veg um morgonen, og kom heim att til Filistarlandet. Men filistarane drog upp til Jizre’el.',
    },
    30: {
        1: 'Då no David og kararne hans kom til Siklag tridje dagen, hadde amalekitarne gjort ei herjeferd i Sudlandet og i Siklag, hadde teke Siklag og sett eld på byen.',
        2: 'Kvendi der i byen hadde dei rana, både store små, og drege av med deim. Dei hadde ikkje drepe nokon, berre teke deim med seg, og fare sin veg.',
        3: 'Då David og kararne hans kom til byen og fekk sjå at han var brend, og fekk høyre at konorne og sønerne og døtterne deira var rana og burtførde,',
        4: 'då sette dei i og gret, både David og folki som var med honom. Dei gret so lenge til dei ikkje orka gråta meir.',
        5: 'Dei tvo konorne åt David var og rana, Ahinoam frå Jizre’el og Abiga’il, kona åt Nabal frå Karmel, var og hertekne.',
        6: 'David kom i stor knipa; folki hans tala frampå um å steina honom, so beiskeleg innharme var dei alle i hop for tapet av sønerne og døtterne sine. Men David henta styrke hjå Herren, sin Gud.',
        7: 'David baud presten Abjatar Ahimeleksson: «Kom hit med messehakelen!» Abjatar kom fram til David med messehakelen.',
        8: 'David spurde so Herren: «Skal eg setja etter desse ransmennerne? Kann eg nå deim att?» Han fekk til svar: «Gjer det! Nå deim kann du! Berga kann du!»',
        9: 'So lagde David i veg med dei seks hundrad kararne sine. Dei kom til bekken Besor. Der stogga dei som laut vera etter.',
        10: 'David heldt fram med fire hundrad mann. Tvo hundrad mann stogga og gjekk ikkje yver Besorbekken; dei var for trøytte.',
        11: 'Dei fann ein egyptar liggjande ute på marki, og dei henta honom til David. Og då dei hadde gjeve honom mat å eta og vatn å drikka;',
        12: 'og han fekk eit stykke fikekaka og tvo rosinkakor å eta, livna han til; for han hadde ikkje smaka anten vått eller turt i tri heile døger.',
        13: 'David spurde honom: «Kven høyrer du til, og kvar er du frå?» Han svara: «Ein egyptarsvein er eg, træl hjå ein amalekit. Husbond for frå meg i fyrrdags, av di eg var sjuk.',
        14: 'Me hadde gjort ei herjeferd i Sudlandet og den luten som høyrer til kretarane og den som høyrer til Juda og den som Kaleb åtte, og Siklag hev me brent.»',
        15: 'David spurde: «Vil du syna oss veg til desse ransmennerne?» Han svara: «Gjer eid ved Gud at du ikkje drep meg eller gjev meg i henderne på herren min, so skal eg syna deg vegen til ransmennerne.»',
        16: 'Han synte deim veg, og dei kom yver deim med dei låg utyver marki og åt og drakk og gama seg med det store herfanget dei hadde teke i Filistarlandet og Judalandet.',
        17: 'David hogg deim ned, og heldt på frå skumingi den eine dagen til kvelden den andre dagen. Og ingi livande sjæl berga seg undan, so nær som fire hundrad unggutar, som sette seg på kamelarne og rømde.',
        18: 'So berga David alt det amalekitarne hadde teke. Dei tvo konorne sine berga han og.',
        19: 'Dei sakna ingen anten liten eller stor, søner eller døtter, ikkje noko av herfanget dessmeir eller noko av alt det dei hadde rana med seg; David førde heim att alt i hop.',
        20: 'David tok alle krøteri, bufe og smale, og førde fyre den andre buskapen og sagde: «Dette er herfanget åt David!»',
        21: 'Då David kom til dei tvo hundrad mann som hadde vore for trøytte til å fylgja, og som difor stogga attmed Besorbekken, gjekk dei til møtes med David og fylgjesveinarne hans. Og David gjekk burtåt folki og helsa deim.',
        22: 'Alle illmenni og uvyrderne millom fylgjesveinarne åt David tok til ords og sagde: «Etter di desse ikkje fylgde oss, fær dei ingen ting av det herfanget me berga. Einast kona og borni kann kvar taka med seg heim.»',
        23: 'Men David svara: «Far ikkje soleis, brørne mine, med det som Herren gav oss! Han hev verna oss, og let oss vinna yver ransmennerne som kom yver oss.',
        24: 'Kven vil lyda dykk i dette? Dei som fer i striden, og dei som er att og vaktar tyet, skal hava jamstor lut! Luterne skal skiftast likt!».',
        25: 'Soleis stod det ved lag frå den dagen og alle dagar. Han gjorde det til lov og rett i Israel som gjeld den dag i dag.',
        26: 'Då so David kom til Siklag, sende han noko av herfanget til dei øvste i Juda, til venerne sine, med dei ordi: «Her er ei gåva åt dykk av herfanget frå Herrens uvener!» -',
        27: 'Til dei øvste i Betel, i Ramot i Sudlandet og i Jattir,',
        28: 'i Aroer, i Sifmot, i Estemoa,',
        29: 'i Rakal og i jerahme’elit-byarne og kenitarbyarne,',
        30: 'i Horma, i Bor-Asan, i Atak,',
        31: 'i Hebron, og alle dei staderne der David hadde ferdast med kararne sine.',
    },
    31: {
        1: 'Filistarane gjekk på i striden mot Israel. Israels-mennerne rømde undan for filistarane, og det låg mange falne på Gilboafjellet.',
        2: 'Filistarane sette etter Saul og sønerne hans. Og filistarane felte Jonatan, Abinadab og Malkisua, Sauls-sønerne.',
        3: 'Saul sjølv kom upp i ein hard strid. Og nokre bogeskyttarar råka innpå honom. Saul vreid seg i rædsla for skyttarane.',
        4: 'Og han baud våpnsveinen sin: «Drag sverdet ditt, og støyt det gjenom meg, so ikkje desse u-umskorne skal koma og drepa meg, og skamfara meg!» Men våpnsveinen vilde ikkje; han var altfor rædd. Då tok Saul sverdet sjølv og stupte seg på det.',
        5: 'Då våpnsveinen såg Saul var dåen, stupte han seg ogso på sitt sverd og fylgde honom i dauden.',
        6: 'Den dagen fall dei alle i hop, Saul og dei tri sønerne hans og våpnsveinen, og sameleis alle mennerne hans.',
        7: 'Og då Israels-mennerne på hi sida dalen og på hi sida Jordan gådde at Israels-mennerne hadde rømt, og at Saul og sønerne hans var falne, so rømde dei ut or byarne sine; og filistarane kom og busette seg der.',
        8: 'Dagen etter kom filistarane og plundra liki. Dei fann Saul og dei tri sønerne hans liggjande på Gilboafjellet.',
        9: 'Dei hogg hovudet av honom, og rana våpni hans og sende rundt i Filistarlandet, og let forkynna fagnadbodet i templi åt avgudarne sine og millom folket.',
        10: 'Dei lagde våpni hans i Astarte-templet; og liket hans hengde dei upp på bymuren i Bet-San.',
        11: 'Då folket i Jabes i Gilead høyrde gjete det filistarane hadde gjort med Saul,',
        12: 'tok dei i veg, alle våpnføre karar, gjekk heile natti, tok ned frå muren i Bet-San Sauls lik og liki av sønerne hans, for so til Jabes og brende liki der.',
        13: 'So tok dei og grov beini deira ned under tamariska i Jabes og heldt fasta i sju dagar.',
    },
}
